// Personalized content for municipio pages (ES only, other locales use template)
// Each entry contains a rich, multi-paragraph description unique to the municipality

export const municipiosContent: Record<string, string> = {
  // === BARCELONA ===
  'igualada': 'Igualada, capital de la comarca de la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con sustratos sedimentarios y graníticos de la depresión central catalana, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios profesionales de medición preventiva de radón en Igualada, con detectores pasivos de larga duración y protocolos conformes al CSN, dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nIgualada limita con [Vilanova del Camí](/municipios/vilanova-del-cami), [Santa Margarida de Montbui](/municipios/santa-margarida-de-montbui) y [Òdena](/municipios/odena).',

  'manresa': 'Manresa, capital del Bages, está clasificada como Zona II (exposición alta) al gas radón. La comarca del Bages se asienta sobre formaciones geológicas ricas en materiales graníticos y evaporíticos que favorecen la emanación natural de radón. Los niveles de concentración en esta zona pueden superar significativamente el nivel de referencia de 300 Bq/m3.\n\nComo centro urbano e industrial de referencia en la Catalunya central, Manresa cuenta con un importante parque de edificios residenciales y comerciales donde la medición de radón resulta prioritaria. ACM-2020 realiza mediciones profesionales de la concentración media anual de gas radón, siguiendo la metodología establecida por la normativa vigente.\n\nManresa limita con [Sant Joan de Vilatorrada](/municipios/sant-joan-de-vilatorrada), [Santpedor](/municipios/santpedor), [Navarcles](/municipios/navarcles), [Callús](/municipios/callus), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages), [El Pont de Vilomara i Rocafort](/municipios/el-pont-de-vilomara-i-rocafort) y [Sant Salvador de Guardiola](/municipios/sant-salvador-de-guardiola).',

  'berga': 'Berga, capital del Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales del Prepirineo catalán, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece soluciones integrales de medición preventiva de radón en Berga, desde la instalación de detectores hasta la elaboración de informes técnicos, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nBerga limita con [Gironella](/municipios/gironella), [Casserres](/municipios/casserres) y [Guardiola de Berguedà](/municipios/guardiola-de-bergueda).',

  'vic': 'Vic, capital de la comarca de Osona, está clasificada en Zona II (exposición alta) al gas radón. La Plana de Vic, rodeada de formaciones montañosas, presenta una geología con sustratos arcillosos y graníticos que favorecen la concentración de radón. El clima continental de la zona, con inversiones térmicas frecuentes, puede agravar la acumulación del gas en interiores durante los meses fríos.\n\nComo centro de servicios y comercio de Osona, Vic cuenta con un tejido empresarial diverso que debe cumplir con las obligaciones del RD 1029/2022. ACM-2020 dispone de amplia experiencia en mediciones de radón tanto en edificios residenciales como en centros de trabajo, ofreciendo un servicio adaptado a las necesidades de cada cliente.\n\nVic limita con [Manlleu](/municipios/manlleu), [Torelló](/municipios/torello), [Taradell](/municipios/taradell), [Santa Eugènia de Berga](/municipios/santa-eugenia-de-berga), [Seva](/municipios/seva) y [Tona](/municipios/tona).',

  'terrassa': 'Terrassa, en la comarca del Vallès Occidental, se encuentra clasificada en Zona I (exposición media) al gas radón. Su proximidad a las formaciones montañosas de Sant Llorenç del Munt y la Serra de l\'Obac, con sustratos de conglomerados y calizas, genera niveles moderados de radón que requieren vigilancia preventiva.\n\nComo una de las ciudades más pobladas de Catalunya, Terrassa cuenta con un extenso parque inmobiliario e industrial donde la medición preventiva de radón es recomendable. ACM-2020 ofrece servicios de medición y asesoramiento para propietarios, empresas y administraciones que deseen verificar los niveles de radón en sus inmuebles.\n\nTerrassa limita con [Sabadell](/municipios/sabadell), [Rubí](/municipios/rubí), [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles), [Matadepera](/municipios/matadepera), [Castellar del Vallès](/municipios/castellar-del-valles) y [Vacarisses](/municipios/vacarisses).',

  'sabadell': 'Sabadell, ciudad del Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. La geología del Vallès, con depósitos cuaternarios sobre sustratos graníticos y metamórficos de la Serralada Prelitoral, genera niveles moderados de emanación de radón que hacen recomendable la medición preventiva en edificios.\n\nEl importante tejido industrial y comercial de Sabadell, junto con su densidad urbana, hace conveniente la verificación de niveles de radón en centros de trabajo y viviendas, especialmente en plantas bajas y sótanos. ACM-2020 realiza mediciones profesionales con detectores homologados, proporcionando informes detallados según la normativa vigente.\n\nSabadell limita con [Terrassa](/municipios/terrassa), [Rubí](/municipios/rubí), [Castellar del Vallès](/municipios/castellar-del-valles), [Sentmenat](/municipios/sentmenat), [Palau-solità i Plegamans](/municipios/palau-de-plegamans), [Polinyà](/municipios/polinyà), [Barberà del Vallès](/municipios/barbera-del-valles) y [Badia del Vallès](/municipios/badia-del-valles).',

  'sant-cugat-del-valles': 'Sant Cugat del Vallès se encuentra en Zona I (exposición media) al gas radón. Su ubicación en la vertiente sur de la Serra de Collserola, sobre materiales graníticos y pizarrosos del macizo paleozoico, favorece niveles moderados de radón que hacen aconsejable la realización de mediciones preventivas, especialmente en viviendas unifamiliares y edificios con sótano.\n\nACM-2020 ofrece servicios de medición de radón en Sant Cugat, con especial atención a urbanizaciones y viviendas aisladas que, por su contacto directo con el terreno, pueden presentar niveles superiores a los edificios plurifamiliares.\n\nSant Cugat del Vallès limita con [Rubí](/municipios/rubí), [Cerdanyola del Vallès](/municipios/cerdanyola-del-valles), [El Papiol](/municipios/el-papiol) y [Terrassa](/municipios/terrassa).',

  'la-garriga': 'La Garriga, en el Vallès Oriental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales de la depresión vallesana y la proximidad a las aguas termales características del municipio, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en La Garriga, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, incluyendo viviendas, establecimientos termales y centros de trabajo.\n\nLa Garriga limita con [Figaró-Montmany](/municipios/figaro-montmany), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), municipios de actuación prioritaria, y por otro lado, [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles), y también limita con Cànoves i Samalús, zona sin clasificar.',

  'caldes-de-montbui': 'Caldes de Montbui, en el Vallès Oriental, se sitúa en Zona II (exposición alta) al gas radón. Al igual que La Garriga, Caldes es conocida por sus aguas termales, lo que evidencia una geología activa con fracturas que facilitan la ascensión de radón desde las capas profundas del subsuelo. Las fuentes termales más calientes de la península ibérica se encuentran en este municipio.\n\nLa medición de radón en Caldes de Montbui es prioritaria tanto en viviendas como en los numerosos establecimientos vinculados al termalismo. ACM-2020 ofrece un servicio integral de medición y diagnóstico, con detectores pasivos de larga duración que proporcionan una lectura fiable de la concentración media anual.\n\nCaldes de Montbui limita con [Bigues i Riells](/municipios/bigues-i-riells) y [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana), Lliçà d\'Amunt, [Palau-solita i Plegamans](/municipios/palau-de-plegamans), [Sentmenat](/municipios/sentmenat), Sant Llorenç Savall y Sant Feliu de Codines (municipios en zona 1), y también limita con Gallifa, zona sin clasificar.',

  'sant-celoni': 'Sant Celoni, en el Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. Situado a los pies del Montseny, la geología granítica del macizo y los materiales metamórficos circundantes generan condiciones favorables para la emanación de radón. La proximidad del Parc Natural del Montseny, con sus formaciones rocosas antiguas, contribuye a los elevados niveles registrados.\n\nACM-2020 realiza mediciones de radón en Sant Celoni y municipios del entorno del Montseny, donde la combinación de altitud, geología granítica y clima húmedo puede generar concentraciones significativas en interiores.\n\nSant Celoni limita con los municipios de [Gualba](/municipios/gualba), Riells y Viabrea, Sant Feliu de Buixalleu, [Fogars de la Selva](/municipios/fogars-de-la-selva), [Tordera](/municipios/tordera), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Vallgorguina](/municipios/vallgorguina) y [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera).',

  'olesa-de-montserrat': 'Olesa de Montserrat, en el Baix Llobregat, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación al pie de la montaña de Montserrat, con formaciones de conglomerados sobre base granítica, y la presencia de fallas geológicas en la zona, favorecen la emanación de radón desde el subsuelo.\n\nEl municipio combina un núcleo urbano histórico con zonas residenciales de nueva construcción. En ambos casos, la medición de radón es obligatoria en centros de trabajo según el RD 1029/2022. ACM-2020 ofrece servicios de medición profesional adaptados a cada tipo de edificación.\n\nOlesa de Montserrat limita con [Abrera](/municipios/abrera), [Esparreguera](/municipios/esparreguera), [Monistrol de Montserrat](/municipios/monistrol-de-montserrat) y [Castellbell i el Vilar](/municipios/castellbell-i-el-vilar).',

  'esparreguera': 'Esparreguera, en el Baix Llobregat, está clasificada en Zona II (exposición alta) al gas radón. Situada entre las formaciones de Montserrat y la depresión del Llobregat, la geología del municipio incluye conglomerados, calizas y materiales graníticos que favorecen niveles elevados de radón en el subsuelo.\n\nLa actividad industrial y comercial de Esparreguera, junto con su crecimiento residencial, hacen necesaria la realización de mediciones de radón en centros de trabajo y viviendas. ACM-2020 dispone de los medios técnicos y la experiencia necesaria para realizar estas mediciones de acuerdo con la normativa vigente.\n\nEsparreguera limita con [Olesa de Montserrat](/municipios/olesa-de-montserrat), [Abrera](/municipios/abrera), [Collbató](/municipios/collbato) y [Monistrol de Montserrat](/municipios/monistrol-de-montserrat).',

  'solsona': 'Solsona, capital del Solsonès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales evaporíticos y calizas del interior de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Solsona, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia acreditada en municipios de la Catalunya central.\n\nSolsona limita con [Cardona](/municipios/cardona) y otros municipios del Solsonès.',

  'dosrius': 'Dosrius, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. A diferencia de la mayoría de municipios costeros del Maresme, Dosrius se sitúa en el interior, sobre formaciones graníticas del macizo del Montnegre-Corredor que generan niveles elevados de emanación de radón.\n\nLas viviendas unifamiliares y masias dispersas, muy habituales en Dosrius, presentan un mayor contacto con el terreno y son especialmente vulnerables a la infiltración de radón. ACM-2020 recomienda la medición preventiva en este tipo de construcciones y ofrece soluciones de mitigación en caso necesario.\n\nDosrius limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Vilalba Sasserra](/municipios/vilalba-sasserra), [Vallgorguina](/municipios/vallgorguina), [Arenys de Munt](/municipios/arenys-de-munt), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres), [Mataró](/municipios/mataro), [Argentona](/municipios/argentona) y [La Roca del Vallès](/municipios/la-roca-del-valles).',

  'matadepera': 'Matadepera, en el Vallès Occidental, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie del Parc Natural de Sant Llorenç del Munt, sobre formaciones de conglomerados y sustratos graníticos, genera niveles elevados de radón. El carácter residencial del municipio, con predominio de viviendas unifamiliares aisladas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón especialmente orientados a viviendas unifamiliares y chalets, donde la superficie de contacto con el terreno es mayor y las concentraciones de radón pueden ser significativamente superiores a las de edificios plurifamiliares.\n\nMatadepera limita con [Terrassa](/municipios/terrassa), [Castellar del Vallès](/municipios/castellar-del-valles) y [Vacarisses](/municipios/vacarisses).',

  'barcelona': 'Barcelona, capital de Catalunya, se encuentra clasificada en zona baja de exposición al gas radón. Sin embargo, determinadas zonas del municipio, especialmente las colindantes con Collserola y las áreas sobre sustratos graníticos paleozoicos, pueden presentar niveles puntuales que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Barcelona tanto para particulares como para empresas y administraciones. Aunque el riesgo general es bajo, la verificación es recomendable en plantas bajas, sótanos y locales comerciales situados en zonas con geología favorable a la emanación de radón.\n\nBarcelona limita con [Badalona](/municipios/badalona), [Santa Coloma de Gramenet](/municipios/santa-coloma-de-gramenet), [L\'Hospitalet de Llobregat](/municipios/el-hospitalet-de-llobregat) (zona baja), [Cornellà de Llobregat](/municipios/cornella-de-llobregat) (zona baja), [Sant Feliu de Llobregat](/municipios/sant-feliu-de-llobregat) (zona baja), [Sant Just Desvern](/municipios/sant-just-desvern), [Esplugues de Llobregat](/municipios/esplugues-de-llobregat) (zona baja) y [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles).',

  'badalona': 'Badalona, en la comarca del Barcelonès, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie de la Serra de Marina, con formaciones graníticas y metamórficas de la Serralada Litoral, genera niveles elevados de radón, especialmente en las zonas norte del municipio. El Real Decreto 1029/2022 establece la obligatoriedad de medir la concentración de radón en centros de trabajo situados en esta zona de actuación prioritaria.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Badalona, con atención especial a las edificaciones situadas en las laderas de la Serra de Marina y en las zonas de contacto con el sustrato granítico. El servicio incluye la instalación de detectores pasivos de larga duración y la elaboración de informes técnicos conformes a la normativa vigente.\n\nBadalona limita con [Santa Coloma de Gramenet](/municipios/santa-coloma-de-gramenet), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles), [Tiana](/municipios/tiana) y [Montgat](/municipios/montgat).',

  'mataro': 'Mataró, capital del Maresme, se encuentra clasificada en Zona I (exposición media) al gas radón. Su ubicación entre la franja costera y las formaciones graníticas de la Serralada Litoral genera niveles moderados de radón que hacen recomendable la medición preventiva, especialmente en edificios con sótano y en locales situados en plantas bajas en contacto con el terreno.\n\nACM-2020 realiza mediciones de radón en Mataró y el Maresme, proporcionando informes detallados según la normativa vigente. Para empresas con centros de trabajo en esta zona de actuación prioritaria, el servicio incluye asesoramiento sobre las obligaciones derivadas del RD 1029/2022.\n\nMataró limita con [Dosrius](/municipios/dosrius), [Cabrera de Mar](/municipios/cabrera-de-mar), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres) y [Argentona](/municipios/argentona).',

  'argentona': 'Argentona, en la comarca del Maresme, se encuentra clasificada en Zona I (exposición media) al gas radón. Su ubicación en el interior del Maresme, sobre formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón que hacen recomendable la realización de mediciones, especialmente en viviendas unifamiliares y edificios con plantas bajas o sótanos en contacto con el terreno.\n\nACM-2020 recomienda la medición preventiva de radón en Argentona, particularmente en urbanizaciones y viviendas aisladas. El servicio incluye la instalación de detectores pasivos durante un período mínimo de tres meses para obtener una lectura fiable de la concentración media anual.\n\nArgentona limita con [Òrrius](/municipios/orrius), [Cabrils](/municipios/cabrils), [La Roca del Vallès](/municipios/la-roca-del-valles), [Dosrius](/municipios/dosrius), [Cabrera de Mar](/municipios/cabrera-de-mar) y [Mataró](/municipios/mataro).',

  // === GIRONA ===
  'girona': 'Girona, capital de provincia, está clasificada en Zona I (exposición media) al gas radón. Aunque la ciudad se sitúa en la depresión del Ter-Onyar con predominio de materiales sedimentarios, la proximidad de formaciones graníticas de las Gavarres y del macizo de les Guilleries genera niveles moderados de radón que aconsejan la medición preventiva en determinados edificios.\n\nComo capital de provincia con un importante parque de edificios históricos y centros de trabajo, Girona requiere especial atención en la medición de radón. ACM-2020 ofrece servicios adaptados tanto a edificios de nueva construcción como a inmuebles históricos del casco antiguo, donde las características constructivas pueden favorecer la acumulación de radón.\n\nGirona limita con [Salt](/municipios/salt), [Sarrià de Ter](/municipios/sarria-de-ter), [Banyoles](/municipios/banyoles), [Besalú](/municipios/besalu), Sant Gregori y Quart.',

  'olot': 'Olot, capital de la Garrotxa, se encuentra en Zona II (exposición alta) al gas radón. La geología volcánica de la Garrotxa es única en la península ibérica: los suelos volcánicos, porosos y permeables, permiten la circulación y emanación de radón con facilidad. La zona volcánica de la Garrotxa, con más de 40 conos volcánicos, genera condiciones geológicas excepcionales para la concentración de radón.\n\nEl casco urbano de Olot, construido directamente sobre materiales volcánicos, presenta un riesgo específico que hace imprescindible la medición de radón en viviendas y centros de trabajo. ACM-2020 cuenta con experiencia en mediciones en zonas volcánicas y ofrece soluciones de mitigación adaptadas a las particularidades geológicas de la Garrotxa.\n\nOlot limita con [Les Preses](/municipios/les-preses), [La Vall d\'en Bas](/municipios/la-vall-den-bas), [Sant Joan les Fonts](/municipios/sant-joan-les-fonts), [Castellfollit de la Roca](/municipios/castellfollit-de-la-roca), [Besalú](/municipios/besalu) y [Santa Pau](/municipios/santa-pau).',

  'ripoll': 'Ripoll, capital del Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situada en la confluencia de los ríos Ter y Freser, en pleno Prepirineo catalán, la geología granítica y metamórfica de la zona genera niveles elevados de emanación de radón. La altitud y el clima de montaña favorecen además períodos prolongados con ventanas cerradas, lo que incrementa la acumulación en interiores.\n\nRipoll, con su importante patrimonio arquitectónico románico y un núcleo urbano histórico, requiere especial atención en la medición de radón. ACM-2020 ofrece servicios profesionales de medición adaptados a edificios históricos y centros de trabajo del Ripollès.\n\nRipoll limita con [Sant Joan de les Abadesses](/municipios/sant-joan-de-les-abadesses), [Ribes de Freser](/municipios/ribes-de-freser), [Sant Quirze de Besora](/municipios/sant-quirze-de-besora) y Campdevànol.',

  'camprodon': 'Camprodon, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Este municipio pirenaico, a más de 900 metros de altitud, se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima frío de montaña, con largos períodos de calefacción y ventilación reducida, agrava la concentración del gas en interiores.\n\nLas casas tradicionales de piedra de Camprodon, así como las segundas residencias de montaña, requieren medición de radón. ACM-2020 realiza mediciones en toda la comarca del Ripollès, con experiencia en edificaciones de montaña y conocimiento de las particularidades climáticas que afectan a la concentración de radón.\n\nCamprodon limita con [Llanars](/municipios/llanars), [Sant Joan de les Abadesses](/municipios/sant-joan-de-les-abadesses) y Molló.',

  'puigcerda': 'Puigcerdà, capital de la Cerdanya, se encuentra en Zona II (exposición alta) al gas radón. La Cerdanya, un amplio valle pirenaico a más de 1.100 metros de altitud, presenta una geología granítica y metamórfica que genera niveles muy elevados de emanación de radón. El clima continental de montaña, con temperaturas extremas en invierno, implica largos períodos con ventilación reducida en interiores.\n\nComo centro turístico y de segunda residencia, Puigcerdà cuenta con un parque inmobiliario diverso que requiere evaluación frente al radón. ACM-2020 ofrece mediciones profesionales y asesoramiento tanto para viviendas permanentes como para residencias de temporada en la Cerdanya.\n\nPuigcerdà limita con [Llívia](/municipios/llívia), [Ger](/municipios/ger), [Alp](/municipios/alp) y [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), además de varios municipios franceses del departamento de l\'Ariège.',

  'santa-coloma-de-farners': 'Santa Coloma de Farners, capital de la Selva, está clasificada en Zona II (exposición alta) al gas radón. La comarca de la Selva, con predominio de terrenos graníticos de la depresión prelitoral, presenta niveles significativos de radón. Santa Coloma, conocida por sus aguas termales, evidencia una geología activa que favorece la emanación de gases del subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Santa Coloma de Farners y municipios de la Selva, con especial atención a edificios situados sobre sustratos graníticos y en zonas con actividad termal.\n\nSanta Coloma de Farners limita con [Arbúcies](/municipios/arbucies), [Breda](/municipios/breda), [Sils](/municipios/sils), [Amer](/municipios/amer) y [Anglès](/municipios/angles).',

  'arbucies': 'Arbúcies, en la comarca de la Selva, se encuentra en Zona II (exposición alta) al gas radón. Situada al pie del Montseny, sobre formaciones graníticas paleozoicas, Arbúcies presenta niveles muy elevados de radón. El macizo del Montseny, uno de los batolitos graníticos más importantes de Catalunya, genera condiciones geológicas muy favorables para la emanación de radón.\n\nLas viviendas y masias de Arbúcies, muchas de ellas construidas directamente sobre roca granítica, requieren medición prioritaria de radón. ACM-2020 cuenta con experiencia en mediciones en municipios del Montseny y ofrece soluciones de mitigación adaptadas a edificaciones rurales y de montaña.\n\nArbúcies limita con [Santa Coloma de Farners](/municipios/santa-coloma-de-farners), [Breda](/municipios/breda) y [Osor](/municipios/osor).',

  'besalu': 'Besalú, en la Garrotxa, está clasificada en Zona II (exposición alta) al gas radón. Este municipio medieval, situado en la confluencia del Fluvià y el Capellades, se asienta sobre materiales calizos y volcánicos que favorecen la emanación de radón. La proximidad a la zona volcánica de la Garrotxa incrementa el potencial de concentración.\n\nEl casco histórico de Besalú, con sus edificaciones medievales de piedra, requiere especial atención en la medición de radón debido a las características constructivas de estos edificios. ACM-2020 ofrece servicios de medición profesional con experiencia en patrimonio arquitectónico histórico.\n\nBesalú limita con [Olot](/municipios/olot), [Castellfollit de la Roca](/municipios/castellfollit-de-la-roca), [Banyoles](/municipios/banyoles) y [Figueres](/municipios/figueres).',

  'sant-joan-de-les-abadesses': 'Sant Joan de les Abadesses, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situada en el valle del Ter, en pleno Prepirineo catalán, la geología granítica y metamórfica de la zona genera niveles elevados de radón. El municipio, a unos 770 metros de altitud, experimenta condiciones climáticas que favorecen la acumulación en interiores.\n\nACM-2020 realiza mediciones de radón en Sant Joan de les Abadesses y el Ripollès, proporcionando informes detallados y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia de 300 Bq/m3.\n\nSant Joan de les Abadesses limita con [Ripoll](/municipios/ripoll), [Camprodon](/municipios/camprodon) y Ogassa.',

  'banyoles': 'Banyoles, capital del Pla de l\'Estany, está clasificada en Zona I (exposición media) al gas radón. La cuenca lacustre de Banyoles, con su complejo sistema hidrogeológico y los sustratos calizos y travertínicos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Banyoles, con especial atención a edificios situados en las proximidades del lago y sobre formaciones calcáreas, donde la permeabilidad del terreno puede facilitar la migración de radón hacia el interior de los edificios.\n\nBanyoles limita con [Besalú](/municipios/besalu), [Girona](/municipios/girona), [Figueres](/municipios/figueres) y Mieres.',

  'figueres': 'Figueres, capital del Alt Empordà, se encuentra clasificada en Zona I (exposición media) al gas radón. La llanura empordanesa, con depósitos aluviales sobre sustratos graníticos, presenta niveles moderados de radón. Las zonas norte del municipio, más próximas a las estribaciones pirenaicas, pueden registrar niveles superiores.\n\nComo capital comarcal con un importante sector de servicios y comercio, Figueres debe prestar atención a la medición de radón en centros de trabajo. ACM-2020 proporciona servicios de medición profesional con detección pasiva de larga duración conforme a la normativa vigente.\n\nFigueres limita con [Banyoles](/municipios/banyoles), [Besalú](/municipios/besalu), [Roses](/municipios/roses), [Espolla](/municipios/espolla) y Vilafant.',

  'sils': 'Sils, en la comarca de la Selva, está clasificada en Zona II (exposición alta) al gas radón. La geología granítica de la depresión prelitoral en la que se ubica Sils genera condiciones propicias para la emanación de radón. Los sustratos de arenas y gravas sobre base granítica permiten la migración del gas hacia la superficie con relativa facilidad.\n\nACM-2020 recomienda la medición de radón en viviendas y centros de trabajo de Sils, especialmente en edificaciones con plantas bajas en contacto directo con el terreno. El servicio incluye la instalación de detectores pasivos y la elaboración de informes técnicos conformes al RD 1029/2022.\n\nSils limita con [Santa Coloma de Farners](/municipios/santa-coloma-de-farners), [Breda](/municipios/breda), [Vidreres](/municipios/vidreres) y [Hostalric](/municipios/hostalric).',

  'espolla': 'Espolla, en el Alt Empordà, está clasificada en Zona II (exposición alta) al gas radón. Este municipio de la sierra de la Albera, en la frontera con Francia, se asienta sobre formaciones graníticas y metamórficas del extremo oriental de los Pirineos que generan niveles muy elevados de radón.\n\nLa medición de radón en Espolla es obligatoria en centros de trabajo según el RD 1029/2022. ACM-2020 ofrece servicios de medición profesional en municipios del Alt Empordà, con experiencia en zonas de geología granítica pirenaica.\n\nEspolla limita con [Portbou](/municipios/portbou), [Llança](/municipios/llança), [Figueres](/municipios/figueres) y Rabós d\'Empordà.',

  'alp': 'Alp, en la comarca de la Cerdanya, se encuentra en Zona II (exposición alta) al gas radón. Situado a más de 1.100 metros de altitud junto a la estación de esquí de la Masella, Alp se asienta sobre formaciones graníticas pirenaicas que generan niveles muy elevados de radón. El clima frío de montaña implica largos períodos de calefacción con ventilación reducida.\n\nACM-2020 realiza mediciones de radón en Alp y la Cerdanya, con atención especial a residencias de montaña y segundas viviendas donde la ventilación puede ser insuficiente durante períodos prolongados.\n\nAlp limita con [Puigcerdà](/municipios/puigcerda), [Ger](/municipios/ger), [Bagà](/municipios/baga) y [Castellar de n\'Hug](/municipios/castellar-de-n-hug).',

  'llanars': 'Llanars, en el Ripollès, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico del valle de Camprodon, a más de 1.000 metros de altitud, se asienta sobre materiales graníticos que generan niveles elevados de emanación de radón. Su proximidad al macizo de la Comanegra refuerza el potencial de concentración.\n\nACM-2020 ofrece servicios de medición de radón en Llanars y el alto Ripollès, con experiencia en edificaciones de montaña y conocimiento de las condiciones climáticas que afectan a la concentración de radón en interiores.\n\nLlanars limita con [Camprodon](/municipios/camprodon) y Vilallonga de Ter.',

  'ger': 'Ger, en la Cerdanya, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico, situado a más de 1.100 metros de altitud, se asienta sobre formaciones graníticas que generan niveles muy elevados de radón. La Cerdanya es una de las comarcas con mayor concentración de radón de toda Catalunya.\n\nACM-2020 realiza mediciones profesionales de radón en Ger y la Cerdanya, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación en caso de superar los niveles de referencia establecidos por la normativa.\n\nGer limita con [Puigcerdà](/municipios/puigcerda), [Llívia](/municipios/llívia) y [Alp](/municipios/alp).',

  'cadaques': 'Cadaqués, en el Alt Empordà, está clasificado en Zona II (exposición alta) al gas radón. Situado en la península del Cap de Creus, la geología metamórfica y granítica de esta zona, una de las formaciones rocosas más antiguas de Catalunya, genera niveles elevados de radón. Las casas tradicionales de piedra y el núcleo histórico son especialmente vulnerables.\n\nACM-2020 ofrece servicios de medición de radón en Cadaqués, con atención a las particularidades constructivas de los edificios del casco antiguo y las viviendas situadas sobre el sustrato rocoso del Cap de Creus.\n\nCadaqués limita con el Port de la Selva y con [Roses](/municipios/roses). La mayor parte de su perímetro está rodeado por el Mediterráneo y el Parque Natural del Cap de Creus.',

  'portbou': 'Portbou, en el Alt Empordà, se encuentra en Zona II (exposición alta) al gas radón. Este municipio fronterizo, encajado entre las estribaciones orientales de los Pirineos y el Mediterráneo, se asienta sobre formaciones metamórficas y esquistos que favorecen la emanación de radón. La geología de pizarras y esquistos de la sierra de la Albera genera niveles significativos.\n\nACM-2020 realiza mediciones de radón en Portbou y municipios del extremo norte del Alt Empordà, donde la geología pirenaica genera condiciones favorables para la concentración de radón en interiores.\n\nPortbou limita con [Llança](/municipios/llança), [Espolla](/municipios/espolla) y Colera. Al norte limita con Francia.',

  'llança': 'Llança, en el Alt Empordà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones metamórficas y graníticas de las estribaciones orientales de los Pirineos, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Llança, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas y establecimientos turísticos del municipio.\n\nLlança limita con [Portbou](/municipios/portbou), [Espolla](/municipios/espolla) y Colera.',

  'amer': 'Amer, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle medio del Ter, sobre sustratos graníticos del macizo de les Guilleries, Amer presenta niveles elevados de radón. La confluencia geológica entre la Selva y la Garrotxa genera condiciones especialmente favorables para la emanación.\n\nACM-2020 realiza mediciones profesionales de radón en Amer, con experiencia en municipios de la transición entre la Selva y las Guilleries, donde la geología granítica genera algunos de los niveles más elevados de la provincia de Girona.\n\nAmer limita con [Anglès](/municipios/angles), [Osor](/municipios/osor), [Santa Coloma de Farners](/municipios/santa-coloma-de-farners) y Sant Hilari Sacalm.',

  'angles': 'Anglès, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en el valle del río Onyar, sobre formaciones graníticas que generan niveles significativos de radón. La proximidad al macizo de les Guilleries y la Selva interior favorece la concentración del gas en el subsuelo.\n\nACM-2020 ofrece servicios de medición y control de radón en Anglès, con especial atención a las zonas residenciales situadas sobre sustratos graníticos. La medición con detectores pasivos de larga duración permite obtener una lectura fiable de la exposición real.\n\nAnglès limita con [Amer](/municipios/amer), [Santa Coloma de Farners](/municipios/santa-coloma-de-farners) y [Girona](/municipios/girona).',

  'osor': 'Osor, en la comarca de la Selva, se encuentra en Zona II (exposición alta) al gas radón. Este pequeño municipio del valle de les Guilleries se asienta directamente sobre el batolito granítico de les Guilleries, una de las formaciones graníticas más extensas de Catalunya, lo que genera niveles muy elevados de radón.\n\nLa medición de radón en Osor resulta prioritaria debido a la geología granítica del municipio. ACM-2020 cuenta con experiencia en mediciones en municipios rurales de les Guilleries y ofrece soluciones adaptadas a edificaciones tradicionales de piedra.\n\nOsor limita con [Amer](/municipios/amer), [Arbúcies](/municipios/arbucies) y Sant Hilari Sacalm.',

  // === LLEIDA ===
  'la-seu-durgell': 'La Seu d\'Urgell, capital del Alt Urgell, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales graníticos y metamórficos del Prepirineo leridano, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en La Seu d\'Urgell, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios del Pirineo leridano.\n\nLa Seu d\'Urgell limita con [Vielha](/municipios/vielha), [Sort](/municipios/sort), Coll de Nargó, Montferrer i Castellbò y Andorra.',

  'tremp': 'Tremp, capital del Pallars Jussa, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas y margas de la Conca de Tremp en el Prepirineo leridano, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Tremp, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece un servicio profesional adaptado a las condiciones específicas del Prepirineo leridano.\n\nTremp limita con [Sort](/municipios/sort), [El Pont de Suert](/municipios/el-pont-de-suert) y [Ponts](/municipios/ponts).',

  'sort': 'Sort, capital del Pallars Sobira, está clasificada en Zona II (exposición alta) al gas radón. Situado en el Pirineo leridano a más de 700 metros de altitud, Sort se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima de montaña, con inviernos largos y fríos, favorece la acumulación del gas en interiores durante meses.\n\nACM-2020 ofrece servicios de medición de radón en Sort y el Pallars Sobira, con experiencia en municipios de alta montaña donde las condiciones climáticas y geológicas hacen especialmente importante la verificación de los niveles de radón.\n\nSort limita con [Tremp](/municipios/tremp), [La Seu d\'Urgell](/municipios/la-seu-durgell) y [Alins](/municipios/alins).',

  'vielha': 'Vielha, capital de la Val d\'Aran, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales graníticos y metamórficos de alta montaña en el único valle atlántico de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Vielha, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención al parque hotelero y de servicios del municipio.\n\nVielha limita con [El Pont de Suert](/municipios/el-pont-de-suert), [La Seu d\'Urgell](/municipios/la-seu-durgell) y Francia.',

  'el-pont-de-suert': 'El Pont de Suert, en la Alta Ribagorça, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales graníticos y metamórficos del Pirineo central leridano, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en El Pont de Suert, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios de montaña del Pirineo leridano.\n\nEl Pont de Suert limita con [Vielha](/municipios/vielha), [Vilaller](/municipios/vilaller) y [Tremp](/municipios/tremp).',

  'solsona-lleida': 'Solsona, en la comarca del Solsonès (provincia de Lleida), no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con evaporitas y calizas del interior de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Solsona, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal. El servicio incluye la instalación de detectores pasivos y la elaboración de informes técnicos.\n\nSolsona limita con [Cardona](/municipios/cardona) y otros municipios del Solsonès.',

  'ponts': 'Ponts, en la comarca de la Noguera, está clasificado en Zona II (exposición alta) al gas radón. Situado en la transición entre la depresión central y el Prepirineo, Ponts se asienta sobre formaciones geológicas mixtas que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Ponts y la comarca de la Noguera, proporcionando informes técnicos conformes al RD 1029/2022 y asesoramiento sobre medidas de mitigación.\n\nPonts limita con [Balaguer](/municipios/balaguer), [Tremp](/municipios/tremp) y [Cervera](/municipios/cervera).',

  'alins': 'Alins, en el Pallars Sobira, está clasificado en Zona II (exposición alta) al gas radón. Este municipio de alta montaña, situado en la Vall Ferrera a más de 1.000 metros de altitud, se asienta sobre formaciones graníticas y metamórficas del Pirineo axial que generan niveles muy elevados de radón. Las viviendas de piedra tradicionales y las condiciones climáticas extremas de invierno favorecen la concentración.\n\nACM-2020 realiza mediciones de radón en Alins y el alto Pallars, con experiencia en municipios de alta montaña donde las particularidades constructivas y climáticas requieren un enfoque especializado.\n\nAlins limita con [Sort](/municipios/sort) y municipios del Pallars Sobirà. Al norte limita con Andorra y Francia.',

  'vilaller': 'Vilaller, en la Alta Ribagorça, está clasificado en Zona II (exposición alta) al gas radón. Situado en el Pirineo central leridano, la geología granítica y termal de la zona genera niveles muy elevados de radón. La presencia de aguas termales en las proximidades de Vilaller evidencia una actividad geológica que favorece la emanación de gases del subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Vilaller y la Alta Ribagorça, con atención a las edificaciones tradicionales de piedra y a los centros de trabajo del municipio.\n\nVilaller limita con [El Pont de Suert](/municipios/el-pont-de-suert) y municipios de la Alta Ribagorça.',

  // === TARRAGONA ===
  'montblanc': 'Montblanc, capital de la Conca de Barbera, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con calizas y conglomerados de la Conca de Barbera, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Montblanc, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención al patrimonio histórico y los centros de trabajo del municipio.\n\nMontblanc limita con [Valls](/municipios/valls), [Falset](/municipios/falset) y [Tarragona](/municipios/tarragona) (zona baja).',

  'falset': 'Falset, capital del Priorat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con pizarras llicorella sobre base granítica características del Priorat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Falset, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a bodegas y espacios subterráneos de la comarca.\n\nFalset limita con [Reus](/municipios/reus) (zona baja), [Montblanc](/municipios/montblanc), [Gandesa](/municipios/gandesa) y [Almoster](/municipios/almoster).',

  'valls': 'Valls, capital del Alt Camp, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre la llanura del Camp de Tarragona y las formaciones montañosas del interior, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Valls, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a centros de trabajo y viviendas.\n\nValls limita con [Tarragona](/municipios/tarragona) (zona baja), [Reus](/municipios/reus) (zona baja) y [Montblanc](/municipios/montblanc).',

  'gandesa': 'Gandesa, capital de la Terra Alta, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con calizas y materiales sedimentarios de la Terra Alta, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Gandesa, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece un servicio profesional adaptado a particulares y empresas de la comarca.\n\nGandesa limita con [Tortosa](/municipios/tortosa), [Falset](/municipios/falset) y Mora d\'Ebre (sin clasificar).',

  'tortosa': 'Tortosa, capital del Baix Ebre, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos aluviales del tramo final del Ebro y formaciones calizas y margosas, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Tortosa, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas y centros de trabajo del Baix Ebre.\n\nTortosa limita con [Amposta](/municipios/amposta) (zona baja), [Gandesa](/municipios/gandesa) y el límite con la Comunitat Valenciana.',

  'botarell': 'Botarell, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. Este municipio del interior del Camp de Tarragona, próximo a las sierras de Prades y la Mussara, se asienta sobre formaciones geológicas que generan niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Botarell, con atención a viviendas y centros de trabajo donde la medición es obligatoria según el RD 1029/2022.\n\nBotarell limita con [Reus](/municipios/reus) (zona baja), [Almoster](/municipios/almoster) y [Riudecanyes](/municipios/riudecanyes).',

  'aleixar': 'L\'Aleixar, en la comarca del Baix Camp, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, al pie de la sierra de la Mussara con materiales graníticos y metamórficos, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en L\'Aleixar, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, cumpliendo con los protocolos establecidos por el CSN.\n\nL\'Aleixar limita con [Almoster](/municipios/almoster), [Alforja](/municipios/alforja) y [Riudecanyes](/municipios/riudecanyes).',

  'riudecanyes': 'Riudecanyes, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. Situado en las estribaciones de las montañas de Prades, la geología del municipio, con materiales graníticos y metamórficos, genera niveles elevados de emanación de radón.\n\nACM-2020 realiza mediciones de radón en Riudecanyes, proporcionando informes técnicos conformes a la normativa vigente y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia.\n\nRiudecanyes limita con [Botarell](/municipios/botarell), [L\'Aleixar](/municipios/aleixar), [Riudecols](/municipios/riudecols) y [Alforja](/municipios/alforja).',

  'riudecols': 'Riudecols, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. La geología del municipio, en la transición entre el Camp de Tarragona y las sierras interiores, genera niveles elevados de radón que hacen obligatoria la medición en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Riudecols y el Baix Camp interior, con experiencia en la zona y conocimiento de las particularidades geológicas locales.\n\nRiudecols limita con [Riudecanyes](/municipios/riudecanyes), [Alforja](/municipios/alforja) y [Falset](/municipios/falset).',

  'almoster': 'Almoster, en la comarca del Baix Camp, se encuentra clasificado en Zona II (exposición alta) al gas radón. Este municipio del interior del Camp, próximo a las formaciones montañosas de Prades, se asienta sobre sustratos que favorecen la emanación de radón.\n\nLa medición de radón en Almoster es obligatoria en centros de trabajo subterráneos y en lugares donde se procese agua de origen subterráneo, según el RD 1029/2022. ACM-2020 ofrece servicios profesionales de medición y diagnóstico.\n\nAlmoster limita con [Botarell](/municipios/botarell), [L\'Aleixar](/municipios/aleixar) y [Reus](/municipios/reus) (zona baja).',

  'alforja': 'Alforja, en la comarca del Baix Camp, está clasificada en Zona II (exposición alta) al gas radón. Situado en las estribaciones de las montañas de Prades, la geología granítica y metamórfica del municipio genera niveles significativos de radón. La sierra de la Mussara, próxima a Alforja, es una de las zonas con mayor potencial de radón de la provincia de Tarragona.\n\nACM-2020 realiza mediciones profesionales de radón en Alforja, con experiencia en municipios de las sierras del Baix Camp donde la geología genera condiciones especialmente favorables para la concentración de radón.\n\nAlforja limita con [L\'Aleixar](/municipios/aleixar), [Riudecols](/municipios/riudecols), [Riudecanyes](/municipios/riudecanyes) y [Falset](/municipios/falset).',

  // === BARCELONA - ALT PENEDES ===
  'vilafranca-del-penedes': 'Vilafranca del Penedès, capital de la comarca del Alt Penedès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos sedimentarios cuaternarios sobre sustratos calizos y margosos de la depresión del Penedès, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nAun así, el radón puede aparecer en cualquier edificio con independencia de su ubicación. ACM-2020 ofrece servicios de medición preventiva de radón en Vilafranca del Penedès, con especial atención a bodegas, cellers y locales con plantas bajo rasante donde la ventilación puede ser limitada.\n\nVilafranca del Penedès limita con [Sant Sadurní d\'Anoia](/municipios/sant-sadurni-danoia) y otros municipios del Alt Penedès.',

  'sant-sadurni-danoia': 'Sant Sadurní d\'Anoia, en el Alt Penedès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones sedimentarias de la depresión prelitoral, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nAun así, la medición preventiva es recomendable, especialmente en cavas, bodegas subterráneas y locales con ventilación limitada. ACM-2020 realiza mediciones de radón en Sant Sadurní d\'Anoia con experiencia en espacios subterráneos vinculados a la industria del cava y el vino.\n\nSant Sadurní d\'Anoia limita con [Gelida](/municipios/gelida), [Vilafranca del Penedès](/municipios/vilafranca-del-penedes) y [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires).',

  'gelida': 'Gelida, en la comarca del Alt Penedès, está clasificada en Zona I (exposición media) al gas radón. Su ubicación en la transición entre la depresión del Penedès y las estribaciones de la Serralada Prelitoral, sobre materiales sedimentarios y calizos, genera niveles moderados de radón que aconsejan la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Gelida, proporcionando informes técnicos conformes al RD 1029/2022 para viviendas y centros de trabajo del municipio.\n\nGelida limita con [Sant Sadurní d\'Anoia](/municipios/sant-sadurni-danoia), [Martorell](/municipios/martorell), [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires) y [Els Hostalets de Pierola](/municipios/els-hostalets-de-pierola).',

  // === BARCELONA - ANOIA (additional) ===
  'vilanova-del-cami': 'Vilanova del Camí, en la comarca de la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con sustratos sedimentarios de la depresión central catalana, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Vilanova del Camí, ya que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece informes técnicos conformes a la normativa vigente.\n\nVilanova del Camí limita con [Igualada](/municipios/igualada) y [Santa Margarida de Montbui](/municipios/santa-margarida-de-montbui).',

  'santa-margarida-de-montbui': 'Santa Margarida de Montbui, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios de las estribaciones de la serra de Montbui, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Santa Margarida de Montbui, dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nSanta Margarida de Montbui limita con [Igualada](/municipios/igualada), [Vilanova del Camí](/municipios/vilanova-del-cami) y [Òdena](/municipios/odena).',

  'piera': 'Piera, en la comarca de la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos aluviales del río Anoia y materiales sedimentarios diversos, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Piera, proporcionando informes técnicos y asesoramiento para viviendas y centros de trabajo, pues el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nPiera limita con [Capellades](/municipios/capellades), [La Pobla de Claramunt](/municipios/la-pobla-de-claramunt), [Masquefa](/municipios/masquefa), [Els Hostalets de Pierola](/municipios/els-hostalets-de-pierola) y [Abrera](/municipios/abrera).',

  'capellades': 'Capellades, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas y travertinos del valle del río Anoia, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Capellades con detectores pasivos de larga duración, dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nCapellades limita con [La Pobla de Claramunt](/municipios/la-pobla-de-claramunt), [Piera](/municipios/piera) y Cabrera d\'Anoia.',

  'la-pobla-de-claramunt': 'La Pobla de Claramunt, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el valle del río Anoia con materiales sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en La Pobla de Claramunt, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece un servicio integral de medición y asesoramiento conforme a la normativa vigente.\n\nLa Pobla de Claramunt limita con [Capellades](/municipios/capellades), [Piera](/municipios/piera) y [Igualada](/municipios/igualada).',

  'els-hostalets-de-pierola': 'Els Hostalets de Pierola, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, entre la depresión del Penedès y la conca de la Anoia, con formaciones sedimentarias, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Els Hostalets de Pierola, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios de la Anoia.\n\nEls Hostalets de Pierola limita con [Masquefa](/municipios/masquefa), [Piera](/municipios/piera), [Abrera](/municipios/abrera) y [Gelida](/municipios/gelida).',

  'masquefa': 'Masquefa, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre el Penedès y la Anoia con materiales sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Masquefa, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y cumple con los protocolos establecidos por el CSN.\n\nMasquefa limita con [Els Hostalets de Pierola](/municipios/els-hostalets-de-pierola), [Piera](/municipios/piera), [Abrera](/municipios/abrera) y [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires).',

  'jorba': 'Jorba, en la comarca de la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones sedimentarias de la depresión central, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Jorba, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes al RD 1029/2022.\n\nJorba limita con [Igualada](/municipios/igualada), [Òdena](/municipios/odena) y [Santa Margarida de Montbui](/municipios/santa-margarida-de-montbui).',

  'odena': 'Òdena, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones sedimentarias de la depresión central catalana, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Òdena, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a naves industriales y centros de trabajo del municipio.\n\nÒdena limita con [Igualada](/municipios/igualada), [Santa Margarida de Montbui](/municipios/santa-margarida-de-montbui) y [Jorba](/municipios/jorba).',

  'santa-maria-de-miralles': 'Santa Maria de Miralles, en la Anoia, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas y margosas de la Anoia sur, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Santa Maria de Miralles, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a masias y edificaciones rurales.\n\nSanta Maria de Miralles limita con [Capellades](/municipios/capellades), [Piera](/municipios/piera) y otros municipios de la Anoia sur.',

  // === BARCELONA - BAGES (additional) ===
  'sant-joan-de-vilatorrada': 'Sant Joan de Vilatorrada, en la comarca del Bages, está clasificado en Zona II (exposición alta) al gas radón. Adyacente a Manresa, el municipio comparte la geología del Bages central, con formaciones evaporíticas y sustratos graníticos que generan niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Joan de Vilatorrada, con experiencia en la comarca del Bages donde los niveles de radón pueden superar significativamente el umbral de referencia de 300 Bq/m3.\n\nSant Joan de Vilatorrada limita con [Manresa](/municipios/manresa), [Callús](/municipios/callus) y [Santpedor](/municipios/santpedor).',

  'santpedor': 'Santpedor, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales evaporíticos y margosos del Bages, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Santpedor, recomendable con carácter preventivo dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nSantpedor limita con [Manresa](/municipios/manresa), [Sant Joan de Vilatorrada](/municipios/sant-joan-de-vilatorrada), [Artés](/municipios/artes), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages) y [Moià](/municipios/moià).',

  'navarcles': 'Navarcles, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Llobregat, sobre formaciones evaporíticas y sedimentarias características del Bages, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Navarcles, con detectores pasivos homologados y elaboración de informes según la normativa vigente.\n\nNavarcles limita con [Manresa](/municipios/manresa), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages), [Artés](/municipios/artes), [Moià](/municipios/moià) y [Calders](/municipios/calders).',

  'sallent': 'Sallent, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, marcada por depósitos potásicos y evaporíticos sobre sustratos más antiguos, genera condiciones favorables para la emanación de radón. La actividad minera histórica de Sallent ha dejado un subsuelo con características particulares que pueden afectar a la concentración del gas.\n\nACM-2020 ofrece servicios de medición de radón en Sallent, con atención a las particularidades geológicas derivadas de la historia minera del municipio.\n\nSallent limita con [Balsareny](/municipios/balsareny), [Súria](/municipios/suria) y [Navarcles](/municipios/navarcles).',

  'suria': 'Súria, en el Bages, está clasificada en Zona II (exposición alta) al gas radón. Al igual que otros municipios del Bages con tradición minera de potasa, Súria se asienta sobre formaciones evaporíticas y graníticas que generan niveles elevados de radón. Las cavidades subterráneas derivadas de la actividad minera pueden influir en la distribución del gas.\n\nACM-2020 realiza mediciones de radón en Súria, proporcionando un servicio profesional adaptado a las condiciones específicas del municipio y cumpliendo con las obligaciones del RD 1029/2022.\n\nSúria limita con [Sallent](/municipios/sallent), [Balsareny](/municipios/balsareny), [Cardona](/municipios/cardona) y [Sant Mateu de Bages](/municipios/sant-mateu-de-bages).',

  'cardona': 'Cardona, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones evaporíticas características del Bages y el conocido diapiro salino, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Cardona, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nCardona limita con [Súria](/municipios/suria), [Balsareny](/municipios/balsareny), [Sant Mateu de Bages](/municipios/sant-mateu-de-bages) y [Solsona](/municipios/solsona).',

  'monistrol-de-montserrat': 'Monistrol de Montserrat, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con conglomerados del entorno de Montserrat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Monistrol de Montserrat, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios del entorno de Montserrat.\n\nMonistrol de Montserrat limita con [Esparreguera](/municipios/esparreguera), [Collbató](/municipios/collbato), [Castellbell i el Vilar](/municipios/castellbell-i-el-vilar) y [Olesa de Montserrat](/municipios/olesa-de-montserrat).',

  'castellbell-i-el-vilar': 'Castellbell i el Vilar, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el valle del Llobregat entre Montserrat y Sant Llorenç del Munt con conglomerados y materiales graníticos, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Castellbell i el Vilar, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes a la normativa vigente.\n\nCastellbell i el Vilar limita con [Monistrol de Montserrat](/municipios/monistrol-de-montserrat), [El Pont de Vilomara i Rocafort](/municipios/el-pont-de-vilomara-i-rocafort), [Vacarisses](/municipios/vacarisses) y [Sant Vicenç de Castellet](/municipios/sant-vicenç-de-castellet).',

  'sant-vicenç-de-castellet': 'Sant Vicenç de Castellet, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la confluencia del Llobregat y el Cardener con materiales sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Sant Vicenç de Castellet, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en la comarca del Bages.\n\nSant Vicenç de Castellet limita con [Manresa](/municipios/manresa), [El Pont de Vilomara i Rocafort](/municipios/el-pont-de-vilomara-i-rocafort), [Castellbell i el Vilar](/municipios/castellbell-i-el-vilar) y [Sant Salvador de Guardiola](/municipios/sant-salvador-de-guardiola).',

  'el-pont-de-vilomara-i-rocafort': 'El Pont de Vilomara i Rocafort, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre el Bages y el Vallès con formaciones sedimentarias, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en El Pont de Vilomara i Rocafort, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con detectores pasivos de larga duración y elaboración de informes técnicos.\n\nEl Pont de Vilomara i Rocafort limita con [Castellbell i el Vilar](/municipios/castellbell-i-el-vilar), [Sant Vicenç de Castellet](/municipios/sant-vicenç-de-castellet), [Manresa](/municipios/manresa) y [Vacarisses](/municipios/vacarisses).',

  'artes': 'Artes, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. El municipio se asienta sobre formaciones evaporíticas y sedimentarias del Bages central que generan condiciones propicias para la emanación de radón desde el subsuelo.\n\nACM-2020 realiza mediciones de radón en Artes, proporcionando un servicio profesional integral que incluye medición, diagnóstico e informe técnico conforme a la normativa vigente.\n\nArtés limita con [Santpedor](/municipios/santpedor), [Navarcles](/municipios/navarcles), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages) y Avinyonet de Puigventós.',

  'avinyó': 'Avinyó, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios y evaporíticos del Bages norte, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Avinyó, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios rurales del Bages.\n\nAvinyó limita con [Prats de Lluçanès](/municipios/prats-de-llucanes), [Calders](/municipios/calders), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages) y Oristà.',

  'balsareny': 'Balsareny, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Llobregat, la geología del municipio presenta formaciones evaporíticas y sedimentarias que generan niveles elevados de radón en el subsuelo.\n\nACM-2020 realiza mediciones de radón en Balsareny, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia.\n\nBalsareny limita con [Sallent](/municipios/sallent), [Súria](/municipios/suria), [Cardona](/municipios/cardona) y [Sant Mateu de Bages](/municipios/sant-mateu-de-bages).',

  'callus': 'Callus, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. Próximo a Manresa, el municipio comparte la geología del Bages central con sus formaciones evaporíticas y sustratos que favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Callus, cumpliendo con los protocolos del CSN y proporcionando informes detallados para centros de trabajo y viviendas.\n\nCallús limita con [Manresa](/municipios/manresa), [Sant Joan de Vilatorrada](/municipios/sant-joan-de-vilatorrada) y [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages).',

  'sant-fruitós-de-bages': 'Sant Fruitós de Bages, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios del Bages adyacentes a Manresa, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Sant Fruitós de Bages, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a naves industriales y centros logísticos del municipio.\n\nSant Fruitós de Bages limita con [Manresa](/municipios/manresa), [Callús](/municipios/callus), [Santpedor](/municipios/santpedor), [Artés](/municipios/artes), [Navarcles](/municipios/navarcles), [Calders](/municipios/calders) y [Avinyó](/municipios/avinyó).',

  'sant-salvador-de-guardiola': 'Sant Salvador de Guardiola, en el Bages, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, entre Manresa y Montserrat con formaciones sedimentarias, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Sant Salvador de Guardiola, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas unifamiliares y masias del municipio.\n\nSant Salvador de Guardiola limita con [Manresa](/municipios/manresa), [Sant Vicenç de Castellet](/municipios/sant-vicenç-de-castellet) y [Monistrol de Montserrat](/municipios/monistrol-de-montserrat).',

  'sant-mateu-de-bages': 'Sant Mateu de Bages, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Este municipio del Bages interior se asienta sobre formaciones evaporíticas y sedimentarias que generan condiciones propicias para niveles elevados de radón, especialmente en edificaciones rurales con cimentaciones tradicionales.\n\nACM-2020 realiza mediciones de radón en Sant Mateu de Bages, ofreciendo soluciones adaptadas a edificaciones rurales y de montaña del interior del Bages.\n\nSant Mateu de Bages limita con [Balsareny](/municipios/balsareny), [Cardona](/municipios/cardona) y [Súria](/municipios/suria).',

  // === BARCELONA - BERGUEDA (additional) ===
  'gironella': 'Gironella, en el Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el valle del Llobregat del Prepirineo catalán, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Gironella, recomendable con carácter preventivo dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nGironella limita con [Berga](/municipios/berga), [Casserres](/municipios/casserres), [Cal Rosal](/municipios/cal-rosal) y [Puig-reig](/municipios/puig-reig).',

  'puig-reig': 'Puig-reig, en el Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales del Prepirineo en el valle del Llobregat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Puig-reig, con atención a las colonias industriales y viviendas del municipio, dado que el gas puede aparecer en cualquier edificación con independencia de su clasificación zonal.\n\nPuig-reig limita con [Gironella](/municipios/gironella), [Cal Rosal](/municipios/cal-rosal), [Casserres](/municipios/casserres) y [Berga](/municipios/berga).',

  'baga': 'Bagà, en el Berguedà, está clasificado en Zona II (exposición alta) al gas radón. Situado en el alto Berguedà, a los pies del Cadí-Moixeró, la geología granítica y metamórfica pirenaica genera niveles muy elevados de radón. La altitud del municipio y el clima de montaña favorecen períodos prolongados con ventilación reducida en interiores.\n\nACM-2020 ofrece servicios de medición de radón en Bagà y el alto Berguedà, con experiencia en edificaciones de montaña y conocimiento de las condiciones geológicas del Prepirineo.\n\nBagà limita con [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), Urus, Das, [Alp](/municipios/alp), [Castellar de n\'Hug](/municipios/castellar-de-n-hug), y por otro lado, Gisclareny.',

  'guardiola-de-bergueda': 'Guardiola de Berguedà, en el Berguedà, se encuentra en Zona II (exposición alta) al gas radón. Este municipio del alto Berguedà, puerta de entrada al Cadí-Moixeró, se asienta sobre formaciones graníticas y metamórficas pirenaicas que generan niveles muy elevados de radón.\n\nACM-2020 realiza mediciones de radón en Guardiola de Berguedà, proporcionando informes técnicos para viviendas y centros de trabajo en esta zona de actuación prioritaria del Prepirineo.\n\nGuardiola de Berguedà limita con Bellver de Cerdanya, Riu de Cerdanya, Urus, [Bagà](/municipios/baga), [Castellar de n\'Hug](/municipios/castellar-de-n-hug).',

  'cal-rosal': 'Cal Rosal, en el Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales del Prepirineo en el valle del Llobregat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Cal Rosal, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en el patrimonio industrial del Berguedà.\n\nCal Rosal limita con [Gironella](/municipios/gironella) y [Puig-reig](/municipios/puig-reig), dentro del municipio de Berga comarcal.',

  'casserres': 'Casserres, en el Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el Prepirineo catalán con materiales sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Casserres, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes al RD 1029/2022.\n\nCasserres limita con [Gironella](/municipios/gironella), [Puig-reig](/municipios/puig-reig) y [Berga](/municipios/berga).',

  'la-pobla-de-lillet': 'La Pobla de Lillet, en el Berguedà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el alto Berguedà pirenaico a más de 800 metros de altitud, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en La Pobla de Lillet, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en edificaciones de montaña del Berguedà.\n\nLa Pobla de Lillet limita con [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), [Castellar de n\'Hug](/municipios/castellar-de-n-hug) y Gombrèn.',

  // === BARCELONA - OSONA (additional) ===
  'manlleu': 'Manlleu, en la comarca de Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el meandro del Ter en la Plana de Vic, la geología del municipio presenta sustratos arcillosos y graníticos que favorecen la concentración de radón. El importante tejido industrial de Manlleu, heredero de la tradición textil, requiere verificación sistemática.\n\nACM-2020 realiza mediciones de radón en Manlleu, con atención a centros de trabajo industriales y viviendas del núcleo urbano donde la medición es obligatoria según el RD 1029/2022.\n\nManlleu limita con [Torelló](/municipios/torello), [Roda de Ter](/municipios/roda-de-ter), [Sant Hipòlit de Voltregà](/municipios/sant-hipolit-de-voltrega) y [Vic](/municipios/vic).',

  'tona': 'Tona, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Situado en el extremo sur de la Plana de Vic, sobre formaciones graníticas de la Serralada Prelitoral, Tona presenta niveles elevados de radón. Su proximidad al macizo del Montseny refuerza las condiciones geológicas favorables a la emanación.\n\nACM-2020 ofrece servicios de medición de radón en Tona, con experiencia en municipios de Osona donde la geología granítica genera niveles significativos de radón.\n\nTona limita con [Centelles](/municipios/centelles), [Moià](/municipios/moià), [Taradell](/municipios/taradell), [Seva](/municipios/seva) y [El Brull](/municipios/el-brull).',

  'centelles': 'Centelles, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el paso natural entre el Vallès y la Plana de Vic, sobre formaciones graníticas de la Serralada Prelitoral, el municipio presenta niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Centelles, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación para viviendas y centros de trabajo en esta zona de actuación prioritaria.\n\nCentelles limita con [Aiguafreda](/municipios/aiguafreda), [Tona](/municipios/tona), Sant Martí de Centelles y Seva.',

  'taradell': 'Taradell, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la Plana de Vic, sobre sustratos arcillosos y graníticos, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón. El carácter residencial de Taradell, con numerosas viviendas unifamiliares, incrementa la superficie de contacto con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Taradell, con especial atención a viviendas unifamiliares y chalets donde la exposición potencial es mayor.\n\nTaradell limita con [Vic](/municipios/vic), [Santa Eugènia de Berga](/municipios/santa-eugenia-de-berga), [Seva](/municipios/seva) y [Tona](/municipios/tona).',

  'roda-de-ter': 'Roda de Ter, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en un meandro del Ter, la geología del municipio presenta materiales graníticos y sedimentarios que favorecen la emanación de radón.\n\nACM-2020 realiza mediciones de radón en Roda de Ter, proporcionando un servicio profesional conforme al RD 1029/2022 para centros de trabajo y viviendas del municipio.\n\nRoda de Ter limita con [Manlleu](/municipios/manlleu), [Torelló](/municipios/torello), [Sant Hipòlit de Voltregà](/municipios/sant-hipolit-de-voltrega) y [Santa Eugènia de Berga](/municipios/santa-eugenia-de-berga).',

  'seva': 'Seva, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la transición entre la Plana de Vic y las Guilleries, sobre formaciones graníticas, Seva presenta niveles elevados de radón. Las viviendas aisladas y masias del municipio son especialmente vulnerables por su contacto directo con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Seva, con experiencia en edificaciones rurales de Osona y atención a las particularidades constructivas que favorecen la infiltración de radón.\n\nSeva limita con [Tona](/municipios/tona), [El Brull](/municipios/el-brull), [Taradell](/municipios/taradell) y [Centelles](/municipios/centelles).',

  'el-brull': 'El Brull, en Osona, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en las estribaciones del Montseny sobre el Collsacabra, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en El Brull, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios rurales de montaña de Osona.\n\nEl Brull limita con [Tona](/municipios/tona), [Seva](/municipios/seva), Tagamanent y Viladrau.',

  'sant-hipolit-de-voltrega': 'Sant Hipòlit de Voltregà, en Osona, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la Plana de Vic con sustratos sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Sant Hipòlit de Voltregà, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes a la normativa vigente.\n\nSant Hipòlit de Voltregà limita con [Torelló](/municipios/torello), [Roda de Ter](/municipios/roda-de-ter) y [Les Masies de Voltregà](/municipios/les-masies-de-voltrega).',

  'santa-eugenia-de-berga': 'Santa Eugenia de Berga, en Osona, está clasificada en Zona II (exposición alta) al gas radón. Situada en la Plana de Vic, próxima a las estribaciones del Montseny, la geología granítica de la zona genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Santa Eugenia de Berga, con experiencia en municipios de Osona y atención a viviendas y centros de trabajo donde la medición es obligatoria.\n\nSanta Eugènia de Berga limita con [Vic](/municipios/vic), [Roda de Ter](/municipios/roda-de-ter) y [Taradell](/municipios/taradell).',

  'sant-pere-de-torello': 'Sant Pere de Torelló, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la Plana de Vic norte, sobre materiales graníticos y metamórficos del Prepirineo, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Pere de Torelló, proporcionando informes detallados y asesoramiento sobre medidas de mitigación.\n\nSant Pere de Torelló limita con [Torelló](/municipios/torello), [Sant Quirze de Besora](/municipios/sant-quirze-de-besora) y Vidrà.',

  'torello': 'Torelló, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Ter, en el norte de la Plana de Vic, la geología del municipio presenta materiales graníticos y sedimentarios que generan niveles elevados de radón. El tejido industrial de Torelló, con naves y centros de trabajo, requiere verificación conforme al RD 1029/2022.\n\nACM-2020 realiza mediciones de radón en Torelló, con atención a centros de trabajo industriales y viviendas del municipio.\n\nTorelló limita con [Manlleu](/municipios/manlleu), [Roda de Ter](/municipios/roda-de-ter), [Sant Hipòlit de Voltregà](/municipios/sant-hipolit-de-voltrega), [Sant Pere de Torelló](/municipios/sant-pere-de-torello) y [Sant Quirze de Besora](/municipios/sant-quirze-de-besora).',

  'les-masies-de-voltrega': 'Les Masies de Voltregà, en Osona, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la Plana de Vic con sustratos sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Les Masies de Voltregà, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con especial atención a masias y viviendas aisladas en contacto con el terreno.\n\nLes Masies de Voltregà limita con [Sant Hipòlit de Voltregà](/municipios/sant-hipolit-de-voltrega), [Torelló](/municipios/torello) y [Vic](/municipios/vic).',

  'sant-quirze-de-besora': 'Sant Quirze de Besora, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en la confluencia del Ter y el Besòs, en la transición entre la Plana de Vic y el Ripollès, la geología granítica y metamórfica de la zona genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Quirze de Besora, proporcionando un servicio profesional adaptado a las condiciones geológicas del norte de Osona.\n\nSant Quirze de Besora limita con [Sant Pere de Torelló](/municipios/sant-pere-de-torello), [Torelló](/municipios/torello), [Prats de Lluçanès](/municipios/prats-de-llucanes) y [Ripoll](/municipios/ripoll).',

  'prats-de-llucanes-osona': 'Sant Boi de Lluçanès, en Osona, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la altiplanície del Lluçanès del interior de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Sant Boi de Lluçanès, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios rurales del interior de Catalunya.\n\nSant Boi de Lluçanès limita con [Prats de Lluçanès](/municipios/prats-de-llucanes), [Avinyó](/municipios/avinyó) y Oristà.',

  // === BARCELONA - MOIANES / LLUÇANES ===
  'moià': 'Moià, capital del Moianès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios y evaporíticos del interior de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Moià, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en la Catalunya central.\n\nMoià limita con [Calders](/municipios/calders), [Navarcles](/municipios/navarcles), [Artés](/municipios/artes), [Santpedor](/municipios/santpedor) y [Tona](/municipios/tona).',

  'calders': 'Calders, en el Moianès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre el Bages y el Vallès, con materiales sedimentarios sobre sustratos graníticos, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Calders, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes al RD 1029/2022.\n\nCalders limita con [Moià](/municipios/moià), [Avinyó](/municipios/avinyó), [Sant Fruitós de Bages](/municipios/sant-fruitós-de-bages) y [Navarcles](/municipios/navarcles).',

  'prats-de-llucanes': 'Prats de Lluçanes, capital del Lluçanes, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la altiplanicie del Lluçanes del interior de Catalunya, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Prats de Lluçanes, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece un servicio profesional adaptado a viviendas y centros de trabajo del Lluçanes.\n\nPrats de Lluçanès limita con [Avinyó](/municipios/avinyó), Oristà y [Sant Quirze de Besora](/municipios/sant-quirze-de-besora).',

  // === BARCELONA - VALLES OCCIDENTAL (additional) ===
  'rubí': 'Rubí, en el Vallès Occidental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos cuaternarios de la depresión del Vallès sobre sustratos graníticos de la Serralada Prelitoral, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Rubí, recomendable para polígonos industriales y viviendas en planta baja, dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nRubí limita con [Terrassa](/municipios/terrassa), [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles), [Castellbisbal](/municipios/castellbisbal), [Cerdanyola del Vallès](/municipios/cerdanyola-del-valles) y [El Papiol](/municipios/el-papiol).',

  'castellar-del-valles': 'Castellar del Vallès, en el Vallès Occidental, se encuentra clasificado en Zona I (exposición media) al gas radón. Su proximidad al Parc Natural de Sant Llorenç del Munt, con formaciones de conglomerados sobre base granítica, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Castellar del Vallès, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.\n\nCastellar del Vallès limita con [Sabadell](/municipios/sabadell), [Sentmenat](/municipios/sentmenat), [Matadepera](/municipios/matadepera), [Terrassa](/municipios/terrassa) y Sant Llorenç Savall.',

  'vacarisses': 'Vacarisses, en el Vallès Occidental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con conglomerados y materiales del entorno de Montserrat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Vacarisses, con especial atención a viviendas unifamiliares, dado que el radón puede aparecer en cualquier edificio con independencia de su clasificación zonal.\n\nVacarisses limita con [Terrassa](/municipios/terrassa), [Matadepera](/municipios/matadepera), [Castellbell i el Vilar](/municipios/castellbell-i-el-vilar), [El Pont de Vilomara i Rocafort](/municipios/el-pont-de-vilomara-i-rocafort) y [Ullastrell](/municipios/ullastrell).',

  'ullastrell': 'Ullastrell, en el Vallès Occidental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre la depresión vallesana y las formaciones de Montserrat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Ullastrell, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes a la normativa vigente.\n\nUllastrell limita con [Terrassa](/municipios/terrassa), [Rubí](/municipios/rubí) y [Vacarisses](/municipios/vacarisses).',

  'badia-del-valles': 'Badia del Vallès, en el Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. Aunque se trata de un municipio de carácter urbano denso, la geología subyacente de la depresión vallesana, con depósitos sobre sustratos graníticos, genera niveles moderados de radón que aconsejan la medición preventiva en plantas bajas.\n\nACM-2020 ofrece servicios de medición de radón en Badia del Vallès, con atención a centros de trabajo y viviendas en planta baja o con sótano.\n\nBadia del Vallès limita con [Barberà del Vallès](/municipios/barbera-del-valles) y [Sabadell](/municipios/sabadell).',

  'cerdanyola-del-valles': 'Cerdanyola del Vallès, en el Vallès Occidental, se encuentra en Zona I (exposición media) al gas radón. Su ubicación al pie de la Serra de Collserola, sobre materiales graníticos paleozoicos, genera niveles moderados de radón. La presencia del campus de la Universitat Autònoma y el Parc Tecnològic hacen relevante la medición en estos centros de trabajo.\n\nACM-2020 realiza mediciones de radón en Cerdanyola del Vallès, con experiencia en edificios institucionales y centros de trabajo del Vallès Occidental.\n\nCerdanyola del Vallès limita con [Barberà del Vallès](/municipios/barbera-del-valles), [Sabadell](/municipios/sabadell), [Rubí](/municipios/rubí), [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles) y [Montcada i Reixac](/municipios/montcada-i-reixac).',

  'barbera-del-valles': 'Barberà del Vallès, en el Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. La geología de la depresión vallesana, con depósitos cuaternarios sobre sustratos graníticos, genera niveles moderados de radón. Los importantes polígonos industriales del municipio requieren verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Barberà del Vallès, con atención especial a naves industriales y centros logísticos donde la medición es recomendable.\n\nBarberà del Vallès limita con [Sabadell](/municipios/sabadell), [Cerdanyola del Vallès](/municipios/cerdanyola-del-valles), [Badia del Vallès](/municipios/badia-del-valles) y Montcada i Reixac.',

  'sentmenat': 'Sentmenat, en el Vallès Occidental, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación en la transición entre la depresión vallesana y las formaciones graníticas de la Serralada Prelitoral genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sentmenat, proporcionando informes técnicos para viviendas y centros de trabajo en esta zona de actuación prioritaria.\n\nSentmenat limita con [Castellar del Vallès](/municipios/castellar-del-valles), [Sabadell](/municipios/sabadell), [Palau-solità i Plegamans](/municipios/palau-de-plegamans), [Polinyà](/municipios/polinyà) y [Caldes de Montbui](/municipios/caldes-de-montbui).',

  'palau-de-plegamans': 'Palau-solità i Plegamans, en el Vallès Occidental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos de la depresión vallesana, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Palau-solità i Plegamans, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes conformes al RD 1029/2022.\n\nPalau-solità i Plegamans limita con [Sentmenat](/municipios/sentmenat), [Polinyà](/municipios/polinyà), [Sabadell](/municipios/sabadell) y Lliçà de Munt.',

  'polinyà': 'Polinyà, en el Vallès Occidental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos cuaternarios sobre sustratos de la depresión vallesana, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Polinyà, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a centros de trabajo y viviendas.\n\nPolinyà limita con [Sentmenat](/municipios/sentmenat), [Palau-solità i Plegamans](/municipios/palau-de-plegamans) y [Sabadell](/municipios/sabadell).',

  'montcada-i-reixac': 'Montcada i Reixac, en el Vallès Occidental, está clasificado en Zona I (exposición media) al gas radón. Situado en la confluencia del Besòs y el Ripoll, al pie de la Serra de Collserola, la geología del municipio presenta materiales graníticos y metamórficos que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Montcada i Reixac, con especial atención a las zonas próximas a Collserola donde la geología granítica puede generar niveles superiores.\n\nMontcada i Reixac limita con [Cerdanyola del Vallès](/municipios/cerdanyola-del-valles), [Barberà del Vallès](/municipios/barbera-del-valles), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles) y Santa Coloma de Gramenet.',

  'ripollet': 'Ripollet, en el Vallès Occidental, se encuentra en zona baja de exposición al gas radón. No obstante, determinadas zonas del municipio próximas al río Ripoll pueden presentar niveles que aconsejen la medición preventiva, especialmente en edificios con sótano o plantas bajo rasante.\n\nACM-2020 ofrece servicios de medición de radón en Ripollet para propietarios y empresas que deseen verificar los niveles de radón en sus inmuebles.\n\nRipollet limita con [Cerdanyola del Vallès](/municipios/cerdanyola-del-valles), [Barberà del Vallès](/municipios/barbera-del-valles) y [Sabadell](/municipios/sabadell).',

  'castellbisbal': 'Castellbisbal, en el Vallès Occidental, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la confluencia del Llobregat y el Anoia, con materiales sedimentarios sobre sustratos graníticos, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Castellbisbal, con atención a los polígonos industriales del municipio donde la medición en centros de trabajo es recomendable.\n\nCastellbisbal limita con [Rubí](/municipios/rubí), [El Papiol](/municipios/el-papiol), [Martorell](/municipios/martorell), [Sant Andreu de la Barca](/municipios/sant-andreu-de-la-barca) y [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires).',

  // === BARCELONA - VALLES ORIENTAL (additional) ===
  'granollers': 'Granollers, capital del Vallès Oriental, está clasificado en Zona I (exposición media) al gas radón. La geología de la depresión vallesana, con depósitos cuaternarios sobre sustratos graníticos y metamórficos, genera niveles moderados de radón. Como centro comercial e industrial del Vallès Oriental, el municipio cuenta con un amplio parque de edificios donde la medición preventiva es recomendable.\n\nACM-2020 ofrece servicios de medición de radón en Granollers, con atención a centros de trabajo, comercios y viviendas del municipio.\n\nGranollers limita con [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles), [Canovelles](/municipios/canovelles), [La Roca del Vallès](/municipios/la-roca-del-valles), [Montornès del Vallès](/municipios/montornes-del-valles) y Montmeló.',

  'mollet-del-valles': 'Mollet del Vallès, en el Vallès Oriental, se encuentra en zona baja de exposición al gas radón. No obstante, las zonas del municipio próximas a las formaciones de Collserola y Gallecs pueden presentar niveles que aconsejen la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Mollet del Vallès para propietarios y empresas que deseen verificar los niveles en sus inmuebles, proporcionando informes técnicos detallados.\n\nMollet del Vallès limita con [Martorelles](/municipios/martorelles), [Parets del Vallès](/municipios/parets-del-valles) (zona baja), [Montornès del Vallès](/municipios/montornes-del-valles) y [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles).',

  'llinars-del-valles': 'Llinars del Vallès, en el Vallès Oriental, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la transición entre la depresión vallesana y la Serralada Litoral, sobre materiales graníticos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Llinars del Vallès, proporcionando informes técnicos conformes al RD 1029/2022.\n\nLlinars del Vallès limita con [La Roca del Vallès](/municipios/la-roca-del-valles), [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera), [Vilalba Sasserra](/municipios/vilalba-sasserra), [Dosrius](/municipios/dosrius), y por otro lado [Cardedeu](/municipios/cardedeu) y Sant Antoni de Vilamajor.',

  'cardedeu': 'Cardedeu, en el Vallès Oriental, se encuentra en Zona I (exposición media) al gas radón. Situado al pie del Montseny, la proximidad a las formaciones graníticas de la Serralada Litoral genera niveles moderados de radón que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Cardedeu, con experiencia en municipios del entorno del Montseny.\n\nCardedeu limita con [La Roca del Vallès](/municipios/la-roca-del-valles), [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles), [Llinars del Vallès](/municipios/llinars-del-valles) y Sant Antoni de Vilamajor.',

  'parets-del-valles': 'Parets del Vallès, en el Vallès Oriental, se encuentra en zona baja de exposición al gas radón. Sin embargo, la medición preventiva es recomendable en edificios con sótano y locales en planta baja, especialmente en las zonas próximas al río Tenes.\n\nACM-2020 ofrece servicios de medición de radón en Parets del Vallès para verificar los niveles en viviendas y centros de trabajo.\n\nParets del Vallès limita con [Mollet del Vallès](/municipios/mollet-del-valles) (zona baja), [Granollers](/municipios/granollers) y [Montornès del Vallès](/municipios/montornes-del-valles).',

  'les-franqueses-del-valles': 'Les Franqueses del Vallès, en el Vallès Oriental, no figuran en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la depresión vallesana próxima a las formaciones del Montseny, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Les Franqueses del Vallès, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para viviendas y centros de trabajo.\n\nLes Franqueses del Vallès limita con [Granollers](/municipios/granollers), [Canovelles](/municipios/canovelles), [La Roca del Vallès](/municipios/la-roca-del-valles), [La Garriga](/municipios/la-garriga) y [Cardedeu](/municipios/cardedeu).',

  'canovelles': 'Canovelles, en el Vallès Oriental, se encuentra en Zona I (exposición media) al gas radón. Adyacente a Granollers, el municipio comparte la geología de la depresión vallesana con niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Canovelles, con atención a centros de trabajo y viviendas donde la verificación de niveles es recomendable.\n\nCanovelles limita con [Granollers](/municipios/granollers), [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles) y [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana).',

  'aiguafreda': 'Aiguafreda, en el Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en el congost del Congost, paso natural entre el Vallès y la Plana de Vic, la geología granítica de la zona genera niveles elevados de radón. La altitud y el entorno montañoso favorecen la concentración del gas.\n\nACM-2020 realiza mediciones de radón en Aiguafreda, con experiencia en municipios del congost donde la geología granítica genera condiciones favorables para la emanación de radón.\n\nAiguafreda limita con [Figaró-Montmany](/municipios/figaro-montmany), [Centelles](/municipios/centelles) y Sant Martí de Centelles.',

  'bigues-i-riells': 'Bigues i Riells, en el Vallès Oriental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la vertiente sur de la Serralada Prelitoral con formaciones graníticas, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Bigues i Riells, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con especial atención a urbanizaciones y viviendas unifamiliares.\n\nBigues i Riells limita con [Caldes de Montbui](/municipios/caldes-de-montbui), [Figaró-Montmany](/municipios/figaro-montmany), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana), y por otro lado, Sant Feliu de Codines, y también limita con Sant Quirze Safaja, zona sin clasificar.',

  // === BARCELONA - BAIX LLOBREGAT (additional) ===
  'martorell': 'Martorell, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. Situado en la confluencia del Llobregat y el Anoia, la geología del municipio presenta materiales sedimentarios sobre sustratos que generan niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Martorell, con atención a los importantes polígonos industriales y centros logísticos del municipio donde la medición es recomendable.\n\nMartorell limita con [Abrera](/municipios/abrera), [Sant Andreu de la Barca](/municipios/sant-andreu-de-la-barca), [Castellbisbal](/municipios/castellbisbal), [Gelida](/municipios/gelida) y [El Papiol](/municipios/el-papiol).',

  'abrera': 'Abrera, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Su proximidad a Montserrat y la geología de transición entre la depresión del Llobregat y las formaciones montañosas generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Abrera, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.\n\nAbrera limita con [Martorell](/municipios/martorell), [Esparreguera](/municipios/esparreguera), [Olesa de Montserrat](/municipios/olesa-de-montserrat), [Collbató](/municipios/collbato), [Sant Andreu de la Barca](/municipios/sant-andreu-de-la-barca) y [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires).',

  'collbato': 'Collbató, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con conglomerados del entorno de Montserrat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Collbató, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y ofrece informes técnicos conformes a la normativa vigente.\n\nCollbató limita con [Esparreguera](/municipios/esparreguera), [Abrera](/municipios/abrera), [Olesa de Montserrat](/municipios/olesa-de-montserrat) y [Monistrol de Montserrat](/municipios/monistrol-de-montserrat).',

  'el-hospitalet-de-llobregat': 'L\'Hospitalet de Llobregat, en el Barcelonès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos aluviales del delta del Llobregat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en L\'Hospitalet de Llobregat, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a sótanos y plantas bajo rasante.\n\nL\'Hospitalet de Llobregat limita con [Barcelona](/municipios/barcelona) (zona baja), [Cornellà de Llobregat](/municipios/cornella-de-llobregat) (zona baja) y [Sant Feliu de Llobregat](/municipios/sant-feliu-de-llobregat) (zona baja).',

  'cornella-de-llobregat': 'Cornellà de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Situado en el delta del Llobregat, sobre depósitos aluviales, el municipio presenta generalmente niveles bajos, aunque la medición preventiva es recomendable en edificios con sótano.\n\nACM-2020 realiza mediciones de radón en Cornellà de Llobregat, proporcionando informes técnicos para centros de trabajo y viviendas.\n\nCornellà de Llobregat limita con [Barcelona](/municipios/barcelona) (zona baja), [L\'Hospitalet de Llobregat](/municipios/el-hospitalet-de-llobregat) (zona baja), [Sant Joan Despí](/municipios/sant-joan-despi) (zona baja) y [Sant Boi de Llobregat](/municipios/sant-boi-de-llobregat) (zona baja).',

  'sant-boi-de-llobregat': 'Sant Boi de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Las zonas del municipio próximas a las elevaciones de la Serralada Litoral pueden presentar niveles ligeramente superiores que aconsejen la medición.\n\nACM-2020 ofrece servicios de medición de radón en Sant Boi de Llobregat para propietarios y empresas que deseen verificar los niveles en sus inmuebles.\n\nSant Boi de Llobregat limita con [Cornellà de Llobregat](/municipios/cornella-de-llobregat) (zona baja), [Gavà](/municipios/gava) (zona baja), [Castelldefels](/municipios/castelldefels) (zona baja) y [Sant Feliu de Llobregat](/municipios/sant-feliu-de-llobregat) (zona baja).',

  'gava': 'Gavà, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos litorales y sedimentarios del delta del Llobregat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Gavà, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para viviendas y centros de trabajo.\n\nGavà limita con [Sant Boi de Llobregat](/municipios/sant-boi-de-llobregat) (zona baja), [Castelldefels](/municipios/castelldefels) (zona baja), [Begues](/municipios/begues) y [Sitges](/municipios/sitges) (zona baja).',

  'castelldefels': 'Castelldefels, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos litorales y formaciones calizas del entorno del macizo del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Castelldefels, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas y centros de trabajo.\n\nCastelldefels limita con [Gavà](/municipios/gava) (zona baja), [Sant Boi de Llobregat](/municipios/sant-boi-de-llobregat) (zona baja) y [Sitges](/municipios/sitges) (zona baja).',

  'sant-feliu-de-llobregat': 'Sant Feliu de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Las zonas norte del municipio, próximas a Collserola, pueden presentar niveles moderados debido a la geología granítica del macizo.\n\nACM-2020 realiza mediciones de radón en Sant Feliu de Llobregat, con atención a las edificaciones situadas en las zonas de contacto con Collserola.\n\nSant Feliu de Llobregat limita con [L\'Hospitalet de Llobregat](/municipios/el-hospitalet-de-llobregat) (zona baja), [Cornellà de Llobregat](/municipios/cornella-de-llobregat) (zona baja), [Sant Joan Despí](/municipios/sant-joan-despi) (zona baja) y [Sant Just Desvern](/municipios/sant-just-desvern).',

  'sant-just-desvern': 'Sant Just Desvern, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. Su ubicación al pie de la Serra de Collserola, sobre materiales graníticos paleozoicos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Sant Just Desvern, con especial atención a viviendas unifamiliares y edificios situados en las laderas de Collserola.\n\nSant Just Desvern limita con [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles), Esplugues de Llobregat y Sant Feliu de Llobregat.',

  'el-papiol': 'El Papiol, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, entre Collserola y el valle del Llobregat con materiales sedimentarios, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en El Papiol, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos conformes al RD 1029/2022.\n\nEl Papiol limita con [Castellbisbal](/municipios/castellbisbal), [Martorell](/municipios/martorell), [Rubí](/municipios/rubí) y [Sant Cugat del Vallès](/municipios/sant-cugat-del-valles).',

  'begues': 'Begues, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas y dolomitas del macizo del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Begues, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas unifamiliares y chalets en contacto con el terreno.\n\nBegues limita con [Olivella](/municipios/olivella), [Gavà](/municipios/gava), [Viladecans](/municipios/viladecans), [Sant Climent de Llobregat](/municipios/sant-climent-de-llobregat) y [Corbera de Llobregat](/municipios/corbera-de-llobregat).',

  'cervelló': 'Cervelló, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre el valle del Llobregat y las formaciones del Ordal, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Cervelló, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para viviendas y centros de trabajo.\n\nCervelló limita con [La Palma de Cervelló](/municipios/la-palma-de-cervello), [Vallirana](/municipios/vallirana), [Corbera de Llobregat](/municipios/corbera-de-llobregat) y [Torrelles de Llobregat](/municipios/torrelles-de-llobregat).',

  'vallirana': 'Vallirana, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en el valle de la riera de Cervelló con formaciones calizas del Ordal, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Vallirana, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas y centros de trabajo.\n\nVallirana limita con [Cervelló](/municipios/cervelló), [Corbera de Llobregat](/municipios/corbera-de-llobregat) y Molins de Rei.',

  'corbera-de-llobregat': 'Corbera de Llobregat, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Situada entre el valle del Llobregat y las formaciones del macizo del Ordal, la geología del municipio genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Corbera de Llobregat, proporcionando informes técnicos conformes a la normativa vigente.\n\nCorbera de Llobregat limita con [Cervelló](/municipios/cervelló), [Vallirana](/municipios/vallirana), [Begues](/municipios/begues), [La Palma de Cervelló](/municipios/la-palma-de-cervello) y [Torrelles de Llobregat](/municipios/torrelles-de-llobregat).',

  'la-palma-de-cervello': 'La Palma de Cervelló, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre el valle del Llobregat y las formaciones del Ordal, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en La Palma de Cervelló, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con informes técnicos conformes al RD 1029/2022.\n\nLa Palma de Cervelló limita con [Cervelló](/municipios/cervelló), [Corbera de Llobregat](/municipios/corbera-de-llobregat) y Sant Vicenç dels Horts.',

  'torrelles-de-llobregat': 'Torrelles de Llobregat, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas del macizo del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Torrelles de Llobregat, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas unifamiliares y urbanizaciones del municipio.\n\nTorrelles de Llobregat limita con [Cervelló](/municipios/cervelló), [Corbera de Llobregat](/municipios/corbera-de-llobregat) y [Begues](/municipios/begues).',

  'sant-andreu-de-la-barca': 'Sant Andreu de la Barca, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio, en el valle del Llobregat sobre depósitos sedimentarios, genera niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Andreu de la Barca, con atención a centros de trabajo y viviendas del municipio.\n\nSant Andreu de la Barca limita con [Martorell](/municipios/martorell), [Abrera](/municipios/abrera), [Sant Esteve Sesrovires](/municipios/sant-esteve-sesrovires) y [Castellbisbal](/municipios/castellbisbal).',

  'sant-esteve-sesrovires': 'Sant Esteve Sesrovires, en el Baix Llobregat, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios del entorno del Llobregat, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Sant Esteve Sesrovires, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para viviendas y centros de trabajo.\n\nSant Esteve Sesrovires limita con [Abrera](/municipios/abrera), [Martorell](/municipios/martorell), [Gelida](/municipios/gelida), [Sant Andreu de la Barca](/municipios/sant-andreu-de-la-barca) y [Castellbisbal](/municipios/castellbisbal).',

  // === BARCELONA - BARCELONES (additional) ===
  'santa-coloma-de-gramenet': 'Santa Coloma de Gramenet, en la comarca del Barcelonès, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie de la Serra de Marina, sobre formaciones graníticas y metamórficas de la Serralada Litoral, genera niveles elevados de radón, especialmente en las zonas altas del municipio próximas a la sierra. El Real Decreto 1029/2022 establece la obligatoriedad de medir la concentración de radón en centros de trabajo de esta zona de actuación prioritaria.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Santa Coloma de Gramenet, con atención a las edificaciones situadas en las laderas de la Serra de Marina y en las plantas bajas y sótanos del núcleo urbano.\n\nSanta Coloma de Gramenet limita con [Badalona](/municipios/badalona) y [Montcada i Reixac](/municipios/montcada-i-reixac).',

  // === BARCELONA - MARESME (additional) ===
  'montgat': 'Montgat, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la costa, al pie de las formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Montgat, con atención a viviendas y centros de trabajo situados en las zonas próximas a la sierra.\n\nMontgat limita con [Badalona](/municipios/badalona), [Tiana](/municipios/tiana), [Alella](/municipios/alella) y [el Masnou](/municipios/el-masnou).',

  'tiana': 'Tiana, en el Maresme, se encuentra en Zona I (exposición media) al gas radón. Situado en las estribaciones de la Serralada Litoral, sobre formaciones graníticas, el municipio presenta niveles moderados de radón. Las viviendas unifamiliares del municipio, con contacto directo con el terreno granítico, son especialmente sensibles.\n\nACM-2020 ofrece servicios de medición de radón en Tiana, con especial atención a viviendas unifamiliares y urbanizaciones situadas sobre sustratos graníticos.\n\nTiana limita con [Montgat](/municipios/montgat), [Badalona](/municipios/badalona), [Alella](/municipios/alella), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles) y [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles).',

  // === BARCELONA - GARRAF ===
  'vilanova-i-la-geltru': 'Vilanova i la Geltrú, capital del Garraf, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios de la llanura costera del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Vilanova i la Geltrú, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para propietarios y empresas.\n\nVilanova i la Geltrú limita con [Sitges](/municipios/sitges) (zona baja), [Sant Pere de Ribes](/municipios/sant-pere-de-ribes) (zona baja) y [El Vendrell](/municipios/el-vendrell) (zona baja).',

  'sitges': 'Sitges, en la comarca del Garraf, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas del macizo del Garraf y depósitos litorales, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Sitges, recomendable en edificios históricos del casco antiguo y viviendas con sótano, dado que el radón puede aparecer en cualquier edificación con independencia de su clasificación zonal.\n\nSitges limita con [Vilanova i la Geltrú](/municipios/vilanova-i-la-geltru) (zona baja), [Castelldefels](/municipios/castelldefels) (zona baja), [Gavà](/municipios/gava) (zona baja) y [Sant Pere de Ribes](/municipios/sant-pere-de-ribes) (zona baja).',

  'sant-pere-de-ribes': 'Sant Pere de Ribes, en el Garraf, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios y calizos del macizo del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Sant Pere de Ribes, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, para propietarios y empresas que deseen verificar los niveles.\n\nSant Pere de Ribes limita con [Vilanova i la Geltrú](/municipios/vilanova-i-la-geltru) (zona baja), [Sitges](/municipios/sitges) (zona baja) y [Olivella](/municipios/olivella).',

  'olivella': 'Olivella, en el Garraf, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones calizas y dolomitas del interior del macizo del Garraf, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Olivella, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas unifamiliares y masias del municipio.\n\nOlivella limita con [Begues](/municipios/begues), Sitges y Sant Pere de Ribes.',

  // === GIRONA - GIRONES (additional) ===
  'salt': 'Salt, en el Gironès, está clasificado en Zona I (exposición media) al gas radón. Adyacente a Girona, el municipio comparte la geología de la depresión del Ter-Onyar con niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Salt, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas del municipio.\n\nSalt limita con [Girona](/municipios/girona) y [Sarrià de Ter](/municipios/sarria-de-ter).',

  'sarria-de-ter': 'Sarrià de Ter, en el Gironès, se encuentra en Zona I (exposición media) al gas radón. Situado en el valle del Ter, al norte de Girona, la geología del municipio presenta materiales sedimentarios sobre sustratos que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sarrià de Ter, con informes técnicos conformes a la normativa vigente.\n\nSarrià de Ter limita con [Girona](/municipios/girona), [Salt](/municipios/salt) y Sant Gregori.',

  // === GIRONA - SELVA (additional) ===
  'breda': 'Breda, en la comarca de la Selva, está clasificada en Zona II (exposición alta) al gas radón. Situada al pie del Montseny, sobre formaciones graníticas paleozoicas, Breda presenta niveles elevados de radón. El monasterio románico y el núcleo histórico del municipio, con edificaciones de piedra sobre sustrato granítico, son especialmente sensibles.\n\nACM-2020 realiza mediciones de radón en Breda, con experiencia en municipios del entorno del Montseny donde la geología granítica genera niveles significativos de radón.\n\nBreda limita con [Hostalric](/municipios/hostalric), [Sils](/municipios/sils), [Arbúcies](/municipios/arbucies) y [Santa Coloma de Farners](/municipios/santa-coloma-de-farners).',

  'hostalric': 'Hostalric, en la Selva, se encuentra en Zona II (exposición alta) al gas radón. Situado sobre un promontorio basáltico, la geología del municipio combina materiales volcánicos con sustratos graníticos que generan niveles elevados de radón. El castillo y las murallas medievales de Hostalric se asientan directamente sobre este sustrato rocoso.\n\nACM-2020 ofrece servicios de medición de radón en Hostalric, con atención a las particularidades geológicas del municipio y las edificaciones del casco histórico.\n\nHostalric limita con [Breda](/municipios/breda), [Sils](/municipios/sils) y [Fogars de la Selva](/municipios/fogars-de-la-selva).',

  'vidreres': 'Vidreres, en la Selva, está clasificada en Zona I (exposición media) al gas radón. La geología granítica de la depresión prelitoral genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Vidreres, proporcionando informes técnicos conformes al RD 1029/2022 para viviendas y centros de trabajo.\n\nVidreres limita con [Sils](/municipios/sils), [Lloret de Mar](/municipios/lloret-de-mar) y [Blanes](/municipios/blanes).',

  'lloret-de-mar': 'Lloret de Mar, en la Selva, se encuentra en Zona I (exposición media) al gas radón. La costa de Lloret, con sus formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón. El importante parque hotelero y de servicios del municipio requiere verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Lloret de Mar, con atención a establecimientos turísticos y centros de trabajo donde la medición es recomendable.\n\nLloret de Mar limita con [Blanes](/municipios/blanes) y [Vidreres](/municipios/vidreres).',

  'blanes': 'Blanes, en la Selva, está clasificado en Zona I (exposición media) al gas radón. Situado en la transición entre la Costa Brava y la costa del Maresme, sobre formaciones graníticas de la Serralada Litoral, el municipio presenta niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Blanes, proporcionando informes técnicos para centros de trabajo y viviendas del municipio.\n\nBlanes limita con [Tordera](/municipios/tordera), [Palafolls](/municipios/palafolls), [Malgrat de Mar](/municipios/malgrat-de-mar), [Lloret de Mar](/municipios/lloret-de-mar) y [Macanet de la Selva](/municipios/macanet-de-la-selva).',

  // === GIRONA - GARROTXA (additional) ===
  'les-preses': 'Les Preses, en la Garrotxa, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales volcánicos de la zona volcánica de la Garrotxa, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Les Preses, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios de la Garrotxa.\n\nLes Preses limita con [Olot](/municipios/olot), [La Vall d\'en Bas](/municipios/la-vall-den-bas) y [Santa Pau](/municipios/santa-pau).',

  'santa-pau': 'Santa Pau, en la Garrotxa, se encuentra en Zona II (exposición alta) al gas radón. Este municipio medieval se sitúa en el corazón de la zona volcánica, rodeado de conos volcánicos y coladas de lava que generan suelos porosos y permeables al radón. El casco histórico de piedra es especialmente vulnerable.\n\nACM-2020 realiza mediciones de radón en Santa Pau, con conocimiento de la singular geología volcánica de la Garrotxa y atención a las edificaciones históricas del municipio.\n\nSanta Pau limita con [Olot](/municipios/olot), [Les Preses](/municipios/les-preses), [La Vall d\'en Bas](/municipios/la-vall-den-bas) y [Banyoles](/municipios/banyoles).',

  'la-vall-den-bas': 'La Vall d\'en Bas, en la Garrotxa, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales volcánicos y sedimentarios del amplio valle de la Garrotxa, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en La Vall d\'en Bas, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios de la Garrotxa.\n\nLa Vall d\'en Bas limita con [Olot](/municipios/olot), [Les Preses](/municipios/les-preses), [Santa Pau](/municipios/santa-pau) y Ripollès (municipios limítrofes Zona II).',

  'sant-joan-les-fonts': 'Sant Joan les Fonts, en la Garrotxa, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales volcánicos y basálticos de la zona volcánica de la Garrotxa, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Sant Joan les Fonts, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios de la Garrotxa.\n\nSant Joan les Fonts limita con [Olot](/municipios/olot), [Castellfollit de la Roca](/municipios/castellfollit-de-la-roca) y [Besalú](/municipios/besalu).',

  'castellfollit-de-la-roca': 'Castellfollit de la Roca, en la Garrotxa, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con coladas de lava basáltica del famoso risco sobre el río Fluvià, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Castellfollit de la Roca, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en la geología volcánica de la Garrotxa.\n\nCastellfollit de la Roca limita con [Olot](/municipios/olot), [Sant Joan les Fonts](/municipios/sant-joan-les-fonts) y [Besalú](/municipios/besalu).',

  // === GIRONA - RIPOLLES (additional) ===
  'ribes-de-freser': 'Ribes de Freser, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situado en el valle del Freser, en pleno Pirineo catalán, la geología granítica y metamórfica de la zona genera niveles muy elevados de radón. La altitud del municipio, superior a 900 metros, implica largos períodos con ventilación reducida.\n\nACM-2020 realiza mediciones de radón en Ribes de Freser, con experiencia en municipios del Pirineo donde la combinación de geología granítica y clima de montaña genera concentraciones significativas.\n\nRibes de Freser limita con [Ripoll](/municipios/ripoll) y Campelles.',

  'sant-joan-de-les-abadesses-2': 'Gombrèn, en el Ripollès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales del Prepirineo en el entorno del Ripollès, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Gombrèn, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con experiencia en municipios rurales del Ripollès.\n\nGombrèn limita con [Ripoll](/municipios/ripoll), [Ribes de Freser](/municipios/ribes-de-freser) y [La Pobla de Lillet](/municipios/la-pobla-de-lillet).',

  // === GIRONA - CERDANYA (additional) ===
  'llívia': 'Llívia, en la Cerdanya, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con formaciones graníticas del Pirineo a más de 1.200 metros de altitud, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Llívia, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a las particularidades climáticas de alta montaña que limitan la ventilación natural.\n\nLlívia limita con [Puigcerdà](/municipios/puigcerda) y [Ger](/municipios/ger). Está completamente rodeada de territorio francés excepto por el corredor que la comunica con Puigcerdà.',

  // === GIRONA - EMPORDA (additional) ===
  'la-bisbal-demporda': 'La Bisbal d\'Empordà, capital del Baix Empordà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios sobre sustratos graníticos del macizo de les Gavarres, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en La Bisbal d\'Empordà, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a talleres cerámicos y centros de trabajo.\n\nLa Bisbal d\'Empordà limita con [Palafrugell](/municipios/palafrugell), [Palamós](/municipios/palamos), [Calonge](/municipios/calonge) y Forallac.',

  'roses': 'Roses, en el Alt Empordà, se encuentra clasificada en Zona I (exposición media) al gas radón. La geología del municipio combina formaciones metamórficas del Cap de Creus con depósitos aluviales de la bahía, generando niveles moderados de radón que aconsejan la medición preventiva, especialmente en las zonas próximas a las elevaciones rocosas.\n\nACM-2020 realiza mediciones de radón en Roses, con atención a establecimientos turísticos y centros de trabajo donde la medición es recomendable según el RD 1029/2022.\n\nRoses limita con [Cadaqués](/municipios/cadaques), [Figueres](/municipios/figueres) y Castelló d\'Empúries (sin clasificar).',

  'palafrugell': 'Palafrugell, en el Baix Empordà, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio, entre la costa y el macizo de les Gavarres, presenta formaciones graníticas que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Palafrugell, con atención a viviendas y centros de trabajo del municipio y los núcleos costeros de Calella, Llafranc y Tamariu.\n\nPalafrugell limita con [La Bisbal d\'Empordà](/municipios/la-bisbal-demporda), [Palamós](/municipios/palamos) y Begur.',

  'sant-feliu-de-guixols': 'Sant Feliu de Guíxols, en el Baix Empordà, se encuentra clasificado en Zona I (exposición media) al gas radón. La geología costera del municipio, con formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Feliu de Guíxols, con atención a centros de trabajo y viviendas del municipio.\n\nSant Feliu de Guíxols limita con [Palamós](/municipios/palamos), [Calonge](/municipios/calonge) y Santa Cristina d\'Aro.',

  'palamos': 'Palamós, en el Baix Empordà, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio combina formaciones graníticas costeras con depósitos sedimentarios que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Palamós, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas.\n\nPalamós limita con [Sant Feliu de Guíxols](/municipios/sant-feliu-de-guixols), [Calonge](/municipios/calonge), [La Bisbal d\'Empordà](/municipios/la-bisbal-demporda) y [Palafrugell](/municipios/palafrugell).',

  'calonge': 'Calonge, en el Baix Empordà, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, entre la costa y las formaciones graníticas del interior del Baix Empordà, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Calonge, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a viviendas y centros de trabajo del municipio.\n\nCalonge limita con [Palamós](/municipios/palamos), [Sant Feliu de Guíxols](/municipios/sant-feliu-de-guixols) y [La Bisbal d\'Empordà](/municipios/la-bisbal-demporda).',

  // === LLEIDA (additional) ===
  'lleida': 'Lleida, capital de provincia, se encuentra en zona baja de exposición al gas radón. Situada en la depresión central catalana, sobre depósitos aluviales del Segre, el municipio presenta generalmente niveles bajos de radón. No obstante, la medición preventiva es recomendable en edificios con sótano y plantas bajo rasante.\n\nACM-2020 ofrece servicios de medición de radón en Lleida, proporcionando informes técnicos para propietarios y empresas que deseen verificar los niveles en sus inmuebles.\n\nLleida limita con [Balaguer](/municipios/balaguer), [Mollerussa](/municipios/mollerussa) (zona baja) y [Tàrrega](/municipios/tarrega) (zona baja).',

  'balaguer': 'Balaguer, en la comarca de la Noguera, está clasificada en Zona I (exposición media) al gas radón. Situado en el valle del Segre, en la transición entre la depresión central y el Prepirineo, la geología del municipio genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Balaguer, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas.\n\nBalaguer limita con [Lleida](/municipios/lleida) (zona baja), [Ponts](/municipios/ponts) y [Cervera](/municipios/cervera).',

  'tarrega': 'Tàrrega, capital de la comarca del Urgell, se encuentra en zona baja de exposición al gas radón. Situada en la depresión central catalana, sobre depósitos sedimentarios, el municipio presenta generalmente niveles bajos.\n\nACM-2020 ofrece servicios de medición de radón en Tàrrega para propietarios y empresas que deseen verificar los niveles en sus inmuebles.\n\nTàrrega limita con [Lleida](/municipios/lleida) (zona baja), [Cervera](/municipios/cervera) y [Mollerussa](/municipios/mollerussa) (zona baja).',

  'mollerussa': 'Mollerussa, capital del Pla d\'Urgell, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos aluviales de la llanura del Pla d\'Urgell, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en Mollerussa, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, para propietarios y empresas que deseen verificar los niveles.\n\nMollerussa limita con [Lleida](/municipios/lleida) (zona baja) y [Tàrrega](/municipios/tarrega) (zona baja).',

  'cervera': 'Cervera, capital de la Segarra, está clasificada en Zona I (exposición media) al gas radón. Situada en la meseta de la Segarra, sobre formaciones calizas y margosas de la depresión central, el municipio presenta niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Cervera, proporcionando informes técnicos conformes a la normativa vigente.\n\nCervera limita con [Balaguer](/municipios/balaguer), [Tàrrega](/municipios/tarrega) (zona baja) y [Ponts](/municipios/ponts).',

  // === TARRAGONA (additional) ===
  'tarragona': 'Tarragona, capital de provincia, se encuentra en zona baja de exposición al gas radón. La llanura costera del Camp de Tarragona, sobre depósitos sedimentarios, presenta generalmente niveles bajos. Sin embargo, las zonas próximas a las elevaciones del interior pueden registrar niveles moderados.\n\nACM-2020 realiza mediciones de radón en Tarragona, proporcionando informes técnicos para propietarios y empresas que deseen verificar los niveles en sus inmuebles.\n\nTarragona limita con [Reus](/municipios/reus) (zona baja), [Valls](/municipios/valls), [Cambrils](/municipios/cambrils) (zona baja) y [El Vendrell](/municipios/el-vendrell) (zona baja).',

  'reus': 'Reus, en la comarca del Baix Camp, se encuentra en zona baja de exposición al gas radón. La llanura del Camp de Tarragona presenta generalmente niveles bajos, aunque las zonas del municipio próximas a las sierras interiores pueden registrar niveles moderados.\n\nACM-2020 ofrece servicios de medición de radón en Reus para propietarios y empresas que deseen verificar los niveles en sus inmuebles.\n\nReus limita con [Tarragona](/municipios/tarragona) (zona baja), [Valls](/municipios/valls), [Cambrils](/municipios/cambrils) (zona baja), [Almoster](/municipios/almoster) y [Botarell](/municipios/botarell).',

  'el-vendrell': 'El Vendrell, capital del Baix Penedès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios de la llanura costera del Baix Penedès, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en El Vendrell, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, y proporciona informes técnicos para viviendas y centros de trabajo.\n\nEl Vendrell limita con [Tarragona](/municipios/tarragona) (zona baja), [Calafell](/municipios/calafell) (zona baja) y [Vilanova i la Geltrú](/municipios/vilanova-i-la-geltru) (zona baja).',

  'amposta': 'Amposta, en la comarca del Montsià, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con depósitos aluviales del delta del Ebro, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Amposta, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, para propietarios y empresas que deseen verificar los niveles.\n\nAmposta limita con [Tortosa](/municipios/tortosa) y municipios del Montsià (zona baja).',

  'cambrils': 'Cambrils, en la comarca del Baix Camp, se encuentra en zona baja de exposición al gas radón. La franja costera del Baix Camp presenta generalmente niveles bajos, aunque las zonas interiores próximas a las sierras pueden registrar niveles moderados.\n\nACM-2020 realiza mediciones de radón en Cambrils, proporcionando informes técnicos para centros de trabajo y viviendas.\n\nCambrils limita con [Tarragona](/municipios/tarragona) (zona baja) y [Reus](/municipios/reus) (zona baja).',

  'calafell': 'Calafell, en la comarca del Baix Penedès, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, con materiales sedimentarios de la franja costera del Baix Penedès, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en Calafell, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, para propietarios y empresas que deseen verificar los niveles.\n\nCalafell limita con [El Vendrell](/municipios/el-vendrell) (zona baja) y [Vilanova i la Geltrú](/municipios/vilanova-i-la-geltru) (zona baja).',

  // === MARESME (new municipalities) ===
  'alella': 'Alella, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Situada en las laderas de la Serralada Litoral, entre el litoral y las formaciones graníticas del macizo de la Marina, el municipio presenta sustratos paleozoicos que favorecen la emanación de radón. La tradición vinícola de Alella, con la denominación de origen más antigua de Catalunya, refleja unos suelos graníticos con alta permeabilidad al gas.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Alella, con especial atención a las viviendas unifamiliares y masias del municipio donde el contacto directo con el terreno granítico incrementa el riesgo de infiltración. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nAlella limita con [Vallromanes](/municipios/vallromanes), [Teià](/municipios/teia), [el Masnou](/municipios/el-masnou), [Montgat](/municipios/montgat), [Tiana](/municipios/tiana) y [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles).',

  'cabrera-de-mar': 'Cabrera de Mar, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, entre el litoral mediterráneo y las cimas del macizo de la Marina. Los restos arqueológicos iberos y romanos del Turo d\'en Bosca evidencian la antigüedad de los sustratos rocosos que favorecen la emanación de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Cabrera de Mar, tanto en viviendas como en centros de trabajo. Las edificaciones situadas en las laderas del macizo de la Marina requieren especial atención por su proximidad al sustrato granítico.\n\nCabrera de Mar limita con [Cabrils](/municipios/cabrils), [Argentona](/municipios/argentona), [Mataró](/municipios/mataro), y [Vilassar de Mar](/municipios/vilassar-de-mar).',

  'tordera': 'Tordera, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Situada en la confluencia de la Tordera con la Serralada Litoral, el municipio se asienta sobre formaciones graníticas del macizo del Montnegre-Corredor. El amplio valle fluvial de la Tordera, con depósitos aluviales sobre base granítica, facilita la migración del gas hacia la superficie.\n\nACM-2020 ofrece servicios de medición de radón en Tordera, con atención tanto al núcleo urbano como a las urbanizaciones y masias dispersas del municipio. La medición en centros de trabajo es obligatoria conforme al RD 1029/2022.\n\nTordera limita con [Fogars de la Selva](/municipios/fogars-de-la-selva), Macanet de la Selva, [Lloret de Mar](/municipios/lloret-de-mar), [Sant Celoni](/municipios/sant-celoni), [Blanes](/municipios/blanes), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Pineda de Mar](/municipios/pineda-de-mar), [Santa Susanna](/municipios/santa-susanna) y [Palafolls](/municipios/palafolls).',

  'arenys-de-mar': 'Arenys de Mar, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se extiende desde la costa hasta las primeras estribaciones de la Serralada Litoral, sobre formaciones graníticas y metamórficas que favorecen la emanación de radón. Su puerto pesquero histórico y el núcleo urbano denso cuentan con edificaciones antiguas especialmente vulnerables.\n\nACM-2020 realiza mediciones de radón en Arenys de Mar, con atención a edificios del casco histórico y viviendas en contacto con el sustrato granítico. El servicio incluye detectores pasivos de larga duración conformes a la normativa vigente.\n\nArenys de Mar limita con [Arenys de Munt](/municipios/arenys-de-munt), [Canet de Mar](/municipios/canet-de-mar), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt) y [Caldes d\'Estrac](/municipios/caldes-d-estrac).',

  'cabrils': 'Cabrils, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este municipio residencial se sitúa sobre las formaciones graníticas de la Serralada Litoral, en la vertiente meridional del macizo de la Marina. El predominio de viviendas unifamiliares y urbanizaciones incrementa la superficie de contacto con el terreno y, por tanto, el riesgo de infiltración de radón.\n\nACM-2020 ofrece servicios de medición de radón en Cabrils, especialmente orientados a viviendas unifamiliares y chalets. La verificación de niveles es obligatoria en centros de trabajo ubicados en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nCabrils limita con [Òrrius](/municipios/orrius), [Argentona](/municipios/argentona), [Cabrera de Mar](/municipios/cabrera-de-mar) y [Vilassar de Dalt](/municipios/vilassar-de-dalt), y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar).',

  'sant-andreu-de-llavaneres': 'Sant Andreu de Llavaneres, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se extiende desde la línea de costa hasta las formaciones graníticas de la Serralada Litoral, con sustratos paleozoicos que favorecen la emanación de radón. El carácter residencial del municipio, con numerosas viviendas unifamiliares y campos de golf, incrementa la exposición potencial.\n\nACM-2020 realiza mediciones de radón en Sant Andreu de Llavaneres, con especial atención a urbanizaciones y viviendas aisladas donde el contacto con el terreno granítico es mayor. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Andreu de Llavaneres limita con [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt), [Mataró](/municipios/mataro) y [Dosrius](/municipios/dosrius).',

  'sant-cebria-de-vallalta': 'Sant Cebrià de Vallalta, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el interior del Maresme, entre los macizos del Montnegre y el Corredor, el municipio se asienta sobre formaciones graníticas que generan niveles elevados de radón. El carácter rural y disperso de la edificación favorece el contacto directo con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Sant Cebrià de Vallalta, con atención a masias, viviendas aisladas y centros de trabajo del municipio donde la medición es obligatoria conforme al RD 1029/2022.\n\nSant Cebrià de Vallalta limita con [Sant Celoni](/municipios/sant-celoni), [Tordera](/municipios/tordera), [Pineda de Mar](/municipios/pineda-de-mar), [Calella](/municipios/calella), [Sant Pol de Mar](/municipios/sant-pol-de-mar), [Canet de Mar](/municipios/canet-de-mar) y [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta).',

  'santa-susanna': 'Santa Susanna, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Este municipio costero se sitúa entre la franja litoral y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que favorecen la emanación de radón. La actividad turística del municipio, con numerosos establecimientos hoteleros, requiere verificación de niveles de radón.\n\nACM-2020 realiza mediciones de radón en Santa Susanna, con atención a establecimientos turísticos y centros de trabajo donde la medición es obligatoria según el RD 1029/2022. El servicio incluye detectores pasivos de larga duración y elaboración de informes técnicos.\n\nSanta Susanna limita con [Tordera](/municipios/tordera), [Palafolls](/municipios/palafolls), [Malgrat de Mar](/municipios/malgrat-de-mar) y [Pineda de Mar](/municipios/pineda-de-mar).',

  'vilassar-de-dalt': 'Vilassar de Dalt, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre las formaciones graníticas de la Serralada Litoral, en la vertiente sur del macizo de la Marina. Los sustratos paleozoicos y la presencia de viñas y campos sobre terrenos permeables evidencian la geología favorable a la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Vilassar de Dalt, con atención a viviendas unifamiliares y edificaciones en contacto directo con el sustrato granítico. La medición en centros de trabajo es obligatoria conforme al RD 1029/2022.\n\nVilassar de Dalt limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Òrrius](/municipios/orrius), [Cabrils](/municipios/cabrils), [Premià de Dalt](/municipios/premia-de-dalt) y [Vallromanes](/municipios/vallromanes), y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar).',

  'arenys-de-munt': 'Arenys de Munt, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el interior del Maresme, sobre formaciones graníticas de la Serralada Litoral, el municipio presenta sustratos paleozoicos con alta capacidad de emanación de radón. La orografía montañosa y los torrentes que bajan hacia la costa evidencian la fracturación del sustrato rocoso.\n\nACM-2020 realiza mediciones profesionales de radón en Arenys de Munt, con experiencia en municipios del interior del Maresme donde la geología granítica genera niveles elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nArenys de Munt limita con [Vallgorguina](/municipios/vallgorguina), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Canet de Mar](/municipios/canet-de-mar), [Arenys de Mar](/municipios/arenys-de-mar), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt) y [Dosrius](/municipios/dosrius).',

  'pineda-de-mar': 'Pineda de Mar, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se extiende entre la costa y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que favorecen la emanación de radón. Su importancia como destino turístico, con numerosos hoteles y apartamentos, hace relevante la verificación de niveles de radón en establecimientos de uso público.\n\nACM-2020 ofrece servicios de medición de radón en Pineda de Mar, tanto para viviendas como para establecimientos turísticos y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPineda de Mar limita con [Tordera](/municipios/tordera), [Santa Susanna](/municipios/santa-susanna), [Calella](/municipios/calella) y [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta).',

  'vilassar-de-mar': 'Vilassar de Mar, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Situado en la franja costera del Maresme, el municipio se asienta sobre depósitos aluviales y litorales que atenúan parcialmente la emanación de radón respecto a los municipios interiores. No obstante, la proximidad a las formaciones graníticas de la Serralada Litoral genera niveles moderados que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Vilassar de Mar, con atención a edificios con sótano y locales en planta baja en contacto con el terreno. El servicio incluye detectores pasivos de larga duración y elaboración de informes según la normativa vigente.\n\nVilassar de Mar limita con [Premià de Dalt](/municipios/premia-de-dalt), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Cabrils](/municipios/cabrils), [Cabrera de Mar](/municipios/cabrera-de-mar).',

  'canet-de-mar': 'Canet de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. El municipio se extiende desde el litoral hasta las estribaciones de la Serralada Litoral, sobre formaciones graníticas y metamórficas. El patrimonio modernista del municipio, con obras de Lluís Domènech i Montaner, se asienta sobre sustratos que favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Canet de Mar, con atención tanto a edificios históricos como a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nCanet de Mar limita con [Arenys de Munt](/municipios/arenys-de-munt), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Sant Pol de Mar](/municipios/sant-pol-de-mar) y [Arenys de Mar](/municipios/arenys-de-mar).',

  'caldes-d-estrac': 'Caldes d\'Estrac, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este pequeño municipio costero, conocido históricamente por sus aguas termales, se asienta sobre formaciones graníticas que favorecen tanto la surgencia de aguas mineromedicinales como la emanación de radón. La presencia de aguas termales es un indicador de actividad geológica y fracturación del sustrato.\n\nACM-2020 realiza mediciones de radón en Caldes d\'Estrac, con atención a viviendas, establecimientos termales y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nCaldes d\'Estrac limita con [Arenys de Mar](/municipios/arenys-de-mar) y [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt).',

  'sant-iscle-de-vallalta': 'Sant Iscle de Vallalta, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en pleno macizo del Montnegre-Corredor, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. Su carácter rural y montañoso, con masias y edificaciones dispersas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón en Sant Iscle de Vallalta, con experiencia en municipios del interior del Maresme donde la geología granítica genera condiciones muy favorables para la emanación. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Iscle de Vallalta limita con [Sant Celoni](/municipios/sant-celoni), [Tordera](/municipios/tordera), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Canet de Mar](/municipios/canet-de-mar), [Arenys de Munt](/municipios/arenys-de-munt) y [Vallgorguina](/municipios/vallgorguina).',

  'premia-de-mar': 'Premià de Mar, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Situado en la franja costera del Maresme, el municipio se asienta sobre depósitos litorales y aluviales que moderan la emanación de radón respecto a los municipios interiores. La proximidad a las formaciones graníticas de la Serralada Litoral genera niveles que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Premià de Mar, con atención a edificios con sótano y locales comerciales en planta baja. El servicio incluye la instalación de detectores pasivos y la elaboración de informes conformes a la normativa vigente.\n\nPremià de Mar limita con [Premià de Dalt](/municipios/premia-de-dalt), [Teià](/municipios/teia) y [el Masnou](/municipios/el-masnou).',

  'teia': 'Teià, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en las laderas de la Serralada Litoral, sobre formaciones graníticas paleozoicas que favorecen la emanación de radón. El carácter residencial del municipio, con predominio de viviendas unifamiliares rodeadas de vegetación, incrementa la superficie de contacto con el terreno granítico.\n\nACM-2020 ofrece servicios de medición de radón en Teià, con especial atención a viviendas unifamiliares y chalets donde la infiltración de radón puede ser significativa. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nTeià limita con [el Masnou](/municipios/el-masnou), [Premià de Dalt](/municipios/premia-de-dalt), [Vallromanes](/municipios/vallromanes) y [Alella](/municipios/alella).',

  'orrius': 'Òrrius, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este pequeño municipio del interior del Maresme se sitúa sobre formaciones graníticas de la Serralada Litoral, en la vertiente sur del macizo de la Marina. Su carácter eminentemente rural, con masias y viviendas aisladas sobre terreno granítico, genera condiciones muy favorables para la infiltración de radón.\n\nACM-2020 realiza mediciones de radón en Òrrius, con atención a masias y viviendas unifamiliares donde el contacto directo con el sustrato granítico es determinante. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nÒrrius limita con [Argentona](/municipios/argentona), [La Roca del Vallès](/municipios/la-roca-del-valles), [Cabrils](/municipios/cabrils), [Vilassar de Dalt](/municipios/vilassar-de-dalt) y [Vilanova del Vallès](/municipios/vilanova-del-valles).',

  'palafolls': 'Palafolls, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el tramo bajo del río Tordera, el municipio se asienta sobre depósitos aluviales con base granítica que favorecen la emanación de radón. La proximidad al macizo del Montnegre refuerza el potencial de concentración del gas en el subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Palafolls, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPalafolls limita con [Santa Susanna](/municipios/santa-susanna), [Tordera](/municipios/tordera), [Blanes](/municipios/blanes) y [Malgrat de Mar](/municipios/malgrat-de-mar).',

  'calella': 'Calella, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Este municipio costero, importante destino turístico, se extiende entre el litoral y las estribaciones del macizo del Montnegre sobre formaciones graníticas que favorecen la emanación de radón. Los numerosos establecimientos hoteleros y residenciales requieren verificación de niveles de radón.\n\nACM-2020 realiza mediciones de radón en Calella, con atención a hoteles, edificios residenciales y centros de trabajo donde la medición es obligatoria según el RD 1029/2022. El servicio incluye detectores pasivos de larga duración y elaboración de informes técnicos.\n\nCalella limita con [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Pineda de Mar](/municipios/pineda-de-mar) y [Sant Pol de Mar](/municipios/sant-pol-de-mar).',

  'malgrat-de-mar': 'Malgrat de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en la desembocadura del río Tordera, el municipio se asienta sobre depósitos aluviales y formaciones graníticas que favorecen la emanación de radón. Su carácter turístico, con campings y establecimientos hoteleros, hace relevante la verificación de niveles.\n\nACM-2020 ofrece servicios de medición de radón en Malgrat de Mar, con atención a establecimientos turísticos y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nMalgrat de Mar limita con [Palafolls](/municipios/palafolls), [Santa Susanna](/municipios/santa-susanna) y [Blanes](/municipios/blanes).',

  'sant-vicenc-de-montalt': 'Sant Vicenç de Montalt, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en las estribaciones de la Serralada Litoral, sobre formaciones graníticas paleozoicas del macizo de la Marina. El predominio de viviendas unifamiliares y urbanizaciones en las laderas incrementa el contacto con el sustrato granítico y la exposición potencial al radón.\n\nACM-2020 realiza mediciones de radón en Sant Vicenç de Montalt, con especial atención a urbanizaciones y viviendas en contacto directo con el terreno. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Vicenç de Montalt limita con [Caldes d\'Estrac](/municipios/caldes-d-estrac), [Arenys de Munt](/municipios/arenys-de-munt), [Arenys de Mar](/municipios/arenys-de-mar), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres) y [Dosrius](/municipios/dosrius).',

  'premia-de-dalt': 'Premià de Dalt, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en una posición elevada respecto a la franja costera. Los sustratos paleozoicos y la orografía del municipio generan condiciones favorables para la emanación de radón, especialmente en las zonas altas.\n\nACM-2020 ofrece servicios de medición de radón en Premià de Dalt, con atención a viviendas unifamiliares y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPremià de Dalt limita con [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Teià](/municipios/teia) y [Vallromanes](/municipios/vallromanes), y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar) y [Premià de Mar](/municipios/premia-de-mar).',

  'el-masnou': 'El Masnou, en la comarca del Maresme, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la franja costera del Maresme con depósitos litorales, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en el Masnou, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a edificios residenciales y centros de trabajo del municipio.\n\nEl Masnou limita con [Montgat](/municipios/montgat), [Teià](/municipios/teia), [Alella](/municipios/alella) y [Premià de Mar](/municipios/premia-de-mar).',

  'sant-pol-de-mar': 'Sant Pol de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este municipio costero se sitúa entre el litoral y las estribaciones del macizo del Montnegre-Corredor, sobre formaciones graníticas que favorecen la emanación de radón. El núcleo histórico y las viviendas del municipio requieren verificación de niveles.\n\nACM-2020 ofrece servicios de medición de radón en Sant Pol de Mar, proporcionando informes técnicos para viviendas y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nSant Pol de Mar limita con [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Calella](/municipios/calella) y [Canet de Mar](/municipios/canet-de-mar).',

  // === VALLES ORIENTAL (new municipalities) ===
  'vallromanes': 'Vallromanes, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la vertiente interior de la Serralada Litoral, sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. Su carácter residencial, con predominio de viviendas unifamiliares y fincas agrícolas, incrementa el contacto con el terreno y la exposición potencial.\n\nACM-2020 realiza mediciones de radón en Vallromanes, con especial atención a viviendas unifamiliares y masias del municipio. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nVallromanes limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Premià de Dalt](/municipios/premia-de-dalt), [Teià](/municipios/teia), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Montornès del Vallès](/municipios/montornes-del-valles) y [Alella](/municipios/alella).',

  'figaro-montmany': 'Figaró-Montmany, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en el congost del río Congost, paso natural entre el Vallès y la Plana de Vic, sobre formaciones graníticas y metamórficas que generan niveles elevados de radón. La orografía encajonada del valle y la geología del sustrato favorecen la concentración del gas.\n\nACM-2020 ofrece servicios de medición de radón en Figaró-Montmany, con experiencia en municipios del congost donde la geología granítica y las condiciones orográficas generan niveles significativos. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nFigaró-Montmany limita con [La Garriga](/municipios/la-garriga), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles) y [Bigues i Riells](/municipios/bigues-i-riells), y por otro lado, Sant Marti de Centelles, y también limita con Tagamanent y Sant Quirze Safaja, zona sin clasificar.',

  'montornes-del-valles': 'Montornès del Vallès, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión vallesana y la Serralada Litoral, sobre formaciones graníticas y metamórficas que favorecen la emanación de radón. La combinación de zonas residenciales e industriales hace necesaria la verificación de niveles en diversos tipos de edificaciones.\n\nACM-2020 realiza mediciones de radón en Montornès del Vallès, con atención a centros de trabajo, polígonos industriales y viviendas del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nMontornès del Vallès limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Vallromanes](/municipios/vallromanes), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Martorelles](/municipios/martorelles).',

  'sant-fost-de-campsentelles': 'Sant Fost de Campsentelles, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en las estribaciones de la Serra de Marina, sobre formaciones graníticas y metamórficas de la Serralada Litoral que generan niveles elevados de radón. Las urbanizaciones residenciales en las laderas de la sierra presentan mayor contacto con el sustrato granítico.\n\nACM-2020 ofrece servicios de medición de radón en Sant Fost de Campsentelles, con especial atención a viviendas unifamiliares y urbanizaciones del municipio. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nSant Fost de Campsentelles limita con [Tiana](/municipios/tiana), [Badalona](/municipios/badalona), [Montcada i Reixac](/municipios/montcada-i-reixac), [Martorelles](/municipios/martorelles), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), y por otro lado, La Llagosta y [Mollet del Vallès](/municipios/mollet-del-valles).',

  'santa-eulalia-de-roncana': 'Santa Eulàlia de Ronçana, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en la vertiente sur de la Serralada Prelitoral, sobre formaciones graníticas que generan niveles elevados de radón. El carácter residencial del municipio, con viviendas unifamiliares y urbanizaciones dispersas, incrementa la superficie de contacto con el terreno.\n\nACM-2020 realiza mediciones de radón en Santa Eulàlia de Ronçana, proporcionando informes técnicos para viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nSanta Eulàlia de Ronçana limita con [Caldes de Montbui](/municipios/caldes-de-montbui), [Bigues i Riells](/municipios/bigues-i-riells), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), [Canovelles](/municipios/canovelles) y Lliçà d\'Amunt.',

  'gualba': 'Gualba, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en la vertiente oriental del Montseny, el municipio se asienta sobre formaciones graníticas del macizo que generan niveles elevados de radón. La proximidad al Parc Natural del Montseny y la geología granítica del sustrato favorecen la emanación del gas.\n\nACM-2020 ofrece servicios de medición de radón en Gualba, con experiencia en municipios del entorno del Montseny donde la geología granítica genera condiciones muy favorables para la concentración de radón en interiores.\n\nGualba limita con [Sant Celoni](/municipios/sant-celoni) y Riells i Viabrea, y por otro lado, Campins.',

  'la-roca-del-valles': 'La Roca del Vallès, en la comarca del Vallès Oriental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la transición entre la depresión vallesana y la Serralada Litoral con formaciones graníticas, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 realiza mediciones preventivas de radón en La Roca del Vallès, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con atención a centros comerciales, polígonos industriales y viviendas del municipio.\n\nLa Roca del Vallès limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Dosrius](/municipios/dosrius), [Argentona](/municipios/argentona), [Òrrius](/municipios/orrius), [Vilanova del Vallès](/municipios/vilanova-del-valles), y por otro lado, [Granollers](/municipios/granollers), [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles) i [Cardedeu](/municipios/cardedeu).',

  'martorelles': 'Martorelles, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión vallesana y las estribaciones de la Serra de Marina, sobre formaciones graníticas que favorecen la emanación de radón. Su proximidad a polígonos industriales y centros logísticos hace necesaria la verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Martorelles, proporcionando informes técnicos para viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nMartorelles limita con [Montornès del Vallès](/municipios/montornes-del-valles), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles), y por otro lado [Mollet del Vallès](/municipios/mollet-del-valles) y Montmeló.',

  'vilalba-sasserra': 'Vilalba Sasserra, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Este pequeño municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en la transición hacia el macizo del Montnegre-Corredor. Su reducido tamaño y carácter rural, con viviendas dispersas sobre terreno granítico, genera condiciones favorables para la infiltración de radón.\n\nACM-2020 realiza mediciones de radón en Vilalba Sasserra, con experiencia en municipios del interior del Vallès Oriental donde la geología granítica genera niveles elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nVilalba Sasserra limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Vallgorguina](/municipios/vallgorguina) y [Dosrius](/municipios/dosrius).',

  'vallgorguina': 'Vallgorguina, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en la vertiente interior del macizo del Montnegre-Corredor, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. El entorno boscoso y montañoso del municipio evidencia la geología antigua del sustrato.\n\nACM-2020 ofrece servicios de medición de radón en Vallgorguina, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nVallgorguina limita con [Sant Celoni](/municipios/sant-celoni), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Arenys de Munt](/municipios/arenys-de-munt), [Dosrius](/municipios/dosrius), [Vilalba Sasserra](/municipios/vilalba-sasserra) y [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera).',

  'santa-maria-de-palautordera': 'Santa Maria de Palautordera, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado al pie del Montseny, el municipio se asienta sobre formaciones graníticas del macizo que generan niveles elevados de radón. La proximidad al Parc Natural del Montseny y los torrentes que descienden del macizo evidencian la fracturación del sustrato granítico.\n\nACM-2020 realiza mediciones de radón en Santa Maria de Palautordera, con experiencia en municipios del entorno del Montseny. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSanta Maria de Palautordera limita con [Sant Celoni](/municipios/sant-celoni), [Vallgorguina](/municipios/vallgorguina) y [Llinars del Vallès](/municipios/llinars-del-valles), y por otro lado con Sant Esteve de Palautordera, Fogars de Montclus (ambos zona 1).',

  'ametlla-del-valles': 'L\'Ametlla del Vallès, en la comarca del Vallès Oriental, no figura en las del CSN (RD 1029/2022), lo que indica una probabilidad de riesgo bajo según la metodología de clasificación nacional. Su geología, en la vertiente sur de la Serralada Prelitoral con formaciones graníticas, no supera los umbrales de concentración de radón establecidos por el CSN.\n\nACM-2020 ofrece servicios de medición preventiva de radón en L\'Ametlla del Vallès, dado que el gas puede aparecer en cualquier edificio con independencia de su clasificación zonal, con especial atención a urbanizaciones y viviendas unifamiliares del municipio.\n\nL\'Ametlla del Vallès limita con [Bigues i Riells](/municipios/bigues-i-riells), [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana), [Figaró-Montmany](/municipios/figaro-montmany) y [La Garriga](/municipios/la-garriga).',

  'vilanova-del-valles': 'Vilanova del Vallès, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en la transición entre la depresión vallesana y el macizo de la Marina. Los sustratos paleozoicos del municipio generan condiciones favorables para la emanación de radón.\n\nACM-2020 realiza mediciones de radón en Vilanova del Vallès, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nVilanova del Vallès limita con [La Roca del Vallès](/municipios/la-roca-del-valles), [Òrrius](/municipios/orrius), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Vallromanes](/municipios/vallromanes), [Montornès del Vallès](/municipios/montornes-del-valles), y por otro lado, [Granollers](/municipios/granollers).',

  'santa-maria-de-martorelles': 'Santa Maria de Martorelles, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Este pequeño municipio se sitúa sobre las formaciones graníticas de la Serra de Marina, entre la depresión vallesana y la Serralada Litoral. Los sustratos paleozoicos y la posición orográfica del municipio favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Santa Maria de Martorelles, proporcionando informes técnicos para viviendas y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nSanta Maria de Martorelles limita con [Martorelles](/municipios/martorelles), [Montornès del Vallès](/municipios/montornes-del-valles), [Tiana](/municipios/tiana), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles), [Vallromanes](/municipios/vallromanes) y [Alella](/municipios/alella).',

  // === OSONA (new municipalities) ===
  'sant-sadurni-d-osormort': 'Sant Sadurní d\'Osormort, en la comarca de Osona, está clasificado en Zona II (exposición alta) al gas radón. Este municipio rural de les Guilleries se asienta sobre formaciones graníticas paleozoicas del macizo, una de las formaciones graníticas más extensas de Catalunya. La baja densidad de población y el carácter disperso de las masias generan edificaciones con alto contacto con el terreno granítico.\n\nACM-2020 realiza mediciones de radón en Sant Sadurní d\'Osormort, con experiencia en municipios de les Guilleries donde la geología granítica genera niveles muy elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Sadurní d\'Osormort limita con Viladrau, Espinelves, [Vilanova de Sau](/municipios/vilanova-de-sau), y por otro lado, Folgueroles y Tavernoles.',

  'vilanova-de-sau': 'Vilanova de Sau, en la comarca de Osona, está clasificada en Zona II (exposición alta) al gas radón. Situada en el corazón de les Guilleries, junto al pantano de Sau, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles muy elevados de radón. El entorno montañoso y boscoso del municipio, con masias dispersas, presenta condiciones geológicas muy favorables para la emanación.\n\nACM-2020 ofrece servicios de medición de radón en Vilanova de Sau, con atención a masias y viviendas del municipio donde el contacto con el sustrato granítico es directo. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nVilanova de Sau limita con [Sant Sadurní d\'Osormort](/municipios/sant-sadurni-d-osormort), Sant Hilari Sacalm y Espinelves, y por otro lado, Les Masies de Roda i Tavernoles, y Tavertet, Rupit i Pruit, municipios sin clasificar.',

  // === BERGUEDA (new municipalities) ===
  'castellar-de-n-hug': 'Castellar de n\'Hug, en la comarca del Berguedà, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico, situado a más de 1.300 metros de altitud junto a las fuentes del Llobregat, se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima frío de alta montaña, con largos inviernos y ventilación reducida, agrava la concentración del gas en interiores.\n\nACM-2020 realiza mediciones de radón en Castellar de n\'Hug, con experiencia en edificaciones de alta montaña del Berguedà. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nCastellar de n\'Hug limita con [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), [Bagà](/municipios/baga), [Alp](/municipios/alp), Toses.',

  // === SELVA (new municipalities) ===
  'fogars-de-la-selva': 'Fogars de la Selva, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión prelitoral y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que generan niveles elevados de radón. La geología granítica de la comarca de la Selva es una de las más relevantes de Catalunya en cuanto a emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Fogars de la Selva, con experiencia en municipios de la Selva donde la geología granítica genera condiciones muy favorables para la concentración de radón. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nFogars de la Selva limita con Macanet de la Selva, [Sant Celoni](/municipios/sant-celoni), Sant Feliu de Buixalleu, [Tordera](/municipios/tordera) y [Hostalric](/municipios/hostalric).',
}

export function getMunicipioContent(slug: string): string | undefined {
  return municipiosContent[slug]
}
